(function(A){Object.assign(A.D,{"G1096":{"l":"γίνομαι","o":667,"ar":"<f><o>γίνομαι</o>، صيغة أيونية وعامية (<g>κοινή</g>) بدل الأتيكية <g>γίγν-</g>، </f> <s> <s n=\"1.\">عن الأشخاص والأشياء والحوادث: <b>يأتي إلى الوجود، يُولَد، ينشأ، يحلّ</b>: <r v=\"John.1.15\"></r> <r v=\"John.8.58\"></r>، <r v=\"1Cor.15.37\"></r>؛ عن الظهور الأول على الملأ، <r v=\"Mark.1.4\"></r>، <r v=\"John.1.6\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g> (عن الولادة)، <r v=\"Rom.1.3\"></r>، <r v=\"Gal.4.4\"></r>؛ <g>διά</g>، <r v=\"John.1.3\"></r>؛ <g>βροντή</g> (رعد)، <r v=\"John.12.29\"></r>؛ <g>σεισμός</g> (زلزلة)، <r v=\"Rev.6.12\"></r>؛ <g>γογγυσμός</g> (تذمُّر)، <r v=\"Acts.6.1\"></r>؛ <g>χαρά</g> (فرح)، <r v=\"Acts.8.8\"></r>، وأمثلة أخرى كثيرة مشابهة؛ <g>ἡμέρα</g> (نهار)، <r v=\"Luke.22.66\"></r>، وفي مواضع أخرى؛ <g>ὀψέ</g> (مساء)، <r v=\"Mark.11.19\"></r>؛ <g>πρωΐα</g> (صباح)، <r v=\"Matt.27.1\"></r>؛ <g>νύξ</g> (ليل)، <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">عن الأحداث: <b>يحدث، يقع، يجري، يصير</b>: <r v=\"Matt.5.18\"></r>، <r v=\"Mark.5.14\"></r>، <r v=\"Luke.1.20\"></r> <r v=\"Luke.2.15\"></r>، <r v=\"Acts.4.21\"></r>، <r v=\"2Tim.2.18\"></r>، وفي مواضع أخرى؛ <g>μὴ γένοιτο</g> [في السبعينية ترجمةً لـ <h n=\"H2486\">חָלִילָה</h>، <r v=\"Josh.22.29\"></r>، وفي مواضع أخرى]: <b>حاشا، لا سمح الله</b>: <r v=\"Rom.3.4\"></r>، <r v=\"1Cor.6.15\"></r>، وكثيرًا عند بولس؛ <g>καὶ ἐγένετο, ἐγένετο δέ</g> (وحدث، وكان)، مع الإخباري، <r v=\"Matt.7.28\"></r>، <r v=\"Luke.1.8\"></r>، وفي مواضع أخرى؛ يليه <g>καί</g> والإخباري، <r v=\"Luke.8.1\"></r>، <r v=\"Acts.5.7\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Mark.2.23\"></r>، <r v=\"Luke.3.21\"></r>، وفي مواضع أخرى؛ <g>ὡς δὲ ἐγένετο</g> يليه <g>τοῦ</g> مع المصدر، <r v=\"Acts.10.25\"></r>؛ مع القابل للأشخاص: <i>يصيب أحدًا، يحدث له</i>: مع المصدر، <r v=\"Acts.20.16\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.22.6\"></r>؛ مع ظرف، <g>εὖ</g>، <r v=\"Eph.6.3\"></r>؛ <g>τί ἐγένετο αὐτῷ</g> (ماذا أصابه)، <r v=\"Acts.7.40\"></r> <i>(السبعينية)</i>؛ يليه <g>εἰς</g>، <r v=\"Acts.28.6\"></r>. </s> <s n=\"3.\"><b>يُصنَع، يُعمَل، يُنجَز، يُحفَظ، يُسَنّ، يُرسَم</b>، إلخ: <r v=\"Matt.6.10\"></r> <r v=\"Matt.19.8\"></r>، <r v=\"Mark.2.27\"></r> <r v=\"Mark.11.23\"></r>، <r v=\"Acts.19.26\"></r>، وفي مواضع أخرى؛ يليه <g>διά</g> مع المضاف إليه، <r v=\"Mark.6.2\"></r>، <r v=\"Acts.2.43\"></r>؛ <g>ὑπό</g>، <r v=\"Luke.13.17\"></r>؛ <g>ἐκ</g>، <r v=\"Luke.4.23\"></r>؛ <g>ἐν</g>، <r v=\"1Cor.9.15\"></r>؛ <g>ἀπογραφή</g> (اكتتاب)، <r v=\"Luke.2.2\"></r>؛ <g>ἀνάκρισις</g> (فحص)، أعمال 25: 26؛ <g>ἄφεσις</g> (مغفرة)، <r v=\"Heb.9.22\"></r>؛ <g>ὁ νόμος</g> (الناموس)، <r v=\"Gal.3.17\"></r>؛ <g>τὸ πάσχα</g> (الفصح)، <r v=\"Matt.26.2\"></r>. </s> <s n=\"4.\"><b>يصير، يُجعَل، يغدو</b>: مع الخبر، <r v=\"Matt.4.3\"></r>، <r v=\"Luke.4.3\"></r>، <r v=\"John.2.9\"></r>، <r v=\"1Cor.13.11\"></r>، وفي مواضع أخرى؛ يليه <g>ὡς, ὡσεί</g>، <r v=\"Matt.10.25\"></r>، <r v=\"Mark.9.26\"></r>؛ <g>εἰς</g>، <r v=\"Mark.12.1\"></r>، وفي مواضع أخرى؛ مع المضاف إليه، <r v=\"Rev.11.15\"></r>؛ وكذلك عن العُمر، <r v=\"Luke.2.42\"></r>؛ مع القابل، <g>γ. ἀνδρί</g> (تصير لرجل) [في السبعينية ترجمةً لـ <h n=\"H1961,H376\">הָיָה לְאִישׁ</h>، <r v=\"Ruth.1.12\"></r>، وفي مواضع أخرى]، <r v=\"Rom.7.3\"></r>، 4؛ يليه <g>ἐν</g>، <r v=\"Acts.22.17\"></r>، <r v=\"Rev.1.10\"></r>، وفي مواضع أخرى؛ <g>ἐπάνω</g>، <r v=\"Luke.19.19\"></r>؛ <g>μετά</g> مع المضاف إليه، <r v=\"Mark.16.10\"></r>، <r v=\"Acts.9.19\"></r>؛ يليه <g>εἰς, ἐπί</g>، <g>κατά</g>، مع المنصوب للمكان، <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.27.7\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.3.22\"></r>، <r v=\"2Thess.2.7\"></r>، وفي مواضع أخرى. التام بمعنى الماضي البسيط <g>γέγονα</g>، <r v=\"Matt.25.6\"></r>، <r v=\"Luke.10.36\"></r>، وفي مواضع أخرى. الماضي البسيط <g>ἐγενήθη</g> (بدل <g>ἐγένετο</g>)، <r v=\"Matt.11.23\"></r>، وفي مواضع أخرى. (قارن <g>απο-, δια-, επι-, παρα-, συμ-, παρα-, προ-</g>.)</s> </s>","en":"<f><o>γίνομαι</o>, Ion. and <g>κοινή</g> for Att. <g>γίγν-</g> (M. <i>Pr.</i>, 47; Bl., §6, 8 Mayser, 166 f.), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1961\">היה</h> ;]</e> </et> <s> <s n=\"1.\">of persons, things occurrences, <b>to come into being, be born, arise, come on</b>: <r v=\"John.1.15\"></r> <r v=\"John.8.58\"></r>, <r v=\"1Cor.15.37\"></r>; a first appearance in public, <r v=\"Mark.1.4\"></r>, <r v=\"John.1.6\"></r>, al.; seq. <g>ἐκ</g> (of birth), <r v=\"Rom.1.3\"></r>, <r v=\"Gal.4.4\"></r>; <g>διά</g>, <r v=\"John.1.3\"></r>; <g>βροντή</g>, <r v=\"John.12.29\"></r>; <g>σεισμός</g>, <r v=\"Rev.6.12\"></r>; <g>γογγυσμός</g>, <r v=\"Acts.6.1\"></r>; <g>χαρά</g>, <r v=\"Acts.8.8\"></r>, many other similar exx.; <g>ἡμέρα</g>, <r v=\"Luke.22.66\"></r>, al.; <g>ὀψέ</g>, <r v=\"Mark.11.19\"></r>; <g>πρωΐα</g>, <r v=\"Matt.27.1\"></r>; <g>νύξ</g>, <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">Of events, <b>to come to pass, take place, happen</b>: <r v=\"Matt.5.18\"></r>, <r v=\"Mark.5.14\"></r>, <r v=\"Luke.1.20\"></r> <r v=\"Luke.2.15\"></r>, <r v=\"Acts.4.21\"></r>, <r v=\"2Tim.2.18\"></r>, al.; <g>μὴ γένοιτο</g> [LXX for <h n=\"H2486\">חָלִילָה</h>, <r v=\"Josh.22.29\"></r>, al.], <b> far be it, God forbid</b>: <r v=\"Rom.3.4\"></r> (<i>ICC</i>, in l.), <r v=\"1Cor.6.15\"></r> and freq. in Pl.; <g>καὶ ἐγένετο, ἐγένετο δέ</g> ([in LXX for <h n=\"H1961\">וַיְהִי</h> ;] v. Burton, 142 f.; M, <i>Pr.</i>, 16f.; Dalman, <i>Words</i>, 32 f.; Robertson, <i>Gr.</i>, 1042 f.), c. indic, <r v=\"Matt.7.28\"></r>, <r v=\"Luke.1.8\"></r>, al.; seq. <g>καί</g> et indic., <r v=\"Luke.8.1\"></r>, <r v=\"Acts.5.7\"></r>, al.; c. acc. et inf., <r v=\"Mark.2.23\"></r>, <r v=\"Luke.3.21\"></r>, al.; <g>ὡς δὲ ἐγένετο</g>, seq. <g>τοῦ</g> c. inf., <r v=\"Acts.10.25\"></r>; c. dat. pers., <i>to befall one</i>: c. inf., <r v=\"Acts.20.16\"></r>; c. acc. et inf., <r v=\"Acts.22.6\"></r>; c. adv., <g>εὖ</g>, <r v=\"Eph.6.3\"></r>; <g>τί ἐγένετο αὐτῷ</g> (Field, <i>Notes</i>, 115), <r v=\"Acts.7.40\"></r> <i>(LXX)</i>; seq. <g>εἰς</g>, <r v=\"Acts.28.6\"></r>. </s> <s n=\"3.\"><b>to be made, done, performed, observed, enacted, ordained</b>, etc.: <r v=\"Matt.6.10\"></r> <r v=\"Matt.19.8\"></r>, <r v=\"Mark.2.27\"></r> <r v=\"Mark.11.23\"></r>, <r v=\"Acts.19.26\"></r>, al.; seq. <g>διά</g> c. gen., <r v=\"Mark.6.2\"></r>, <r v=\"Acts.2.43\"></r>; <g>ὑπό</g>, <r v=\"Luke.13.17\"></r>; <g>ἐκ</g>, <r v=\"Luke.4.23\"></r>; <g>ἐν</g>, <r v=\"1Cor.9.15\"></r>; <g>ἀπογραφή</g>, <r v=\"Luke.2.2\"></r>; <g>ἀνάκρισις</g> Ac 25:26; <g>ἄφεσις</g>, <r v=\"Heb.9.22\"></r>; <g>ὁ νόμος</g>, <r v=\"Gal.3.17\"></r>; <g>τὸ πάσχα</g>, <r v=\"Matt.26.2\"></r>. </s> <s n=\"4.\"><b>to become, be made, come to be</b>: c. pred., <r v=\"Matt.4.3\"></r>, <r v=\"Luke.4.3\"></r>, <r v=\"John.2.9\"></r>, <r v=\"1Cor.13.11\"></r>, al.; seq. <g>ὡς, ὡσεί</g>, <r v=\"Matt.10.25\"></r>, <r v=\"Mark.9.26\"></r>; <g>εἰς</g> (M, <i>Pr.</i>, 71f.), <r v=\"Mark.12.1\"></r>o, al.; c. gen. <r v=\"Rev.11.15\"></r>; id., of age, <r v=\"Luke.2.42\"></r>; c. dat., <g>γ. ἀνδρί</g> ([LXX for <h n=\"H1961,H376\">הָיָה לְאִישׁ</h>, <r v=\"Ruth.1.12\"></r>, al. ;] v. Field, <i>Notes</i>, 156), <r v=\"Rom.7.3\"></r>, 4; seq. <g>ἐν</g>, <r v=\"Acts.22.17\"></r>, <r v=\"Rev.1.10\"></r>, al.; <g>ἐπάνω</g>, <r v=\"Luke.19.19\"></r>; <g>μετά</g>, c. gen., <r v=\"Mark.16.10\"></r>, <r v=\"Acts.9.19\"></r>; seq. <g>εἰς, ἐπί</g> (Field, <i>Notes</i>, 135), <g>κατά</g> (ib., 62), c. acc. of place, <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.27.7\"></r>, al.; seq. <g>ἐκ</g>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.3.22\"></r>, <r v=\"2Thess.2.7\"></r>, al. Aoristic pf. <g>γέγονα</g> (M, <i>Pr.</i>, 52, 145f.; Field, <i>Notes</i>, 1f.), <r v=\"Matt.25.6\"></r>, <r v=\"Luke.10.36\"></r>, al. Aor. <g>ἐγενήθη</g> (for <g>ἐγένετο</g>, M, <i>Pr.</i>, 139f.; Mayser, 379), <r v=\"Matt.11.23\"></r>, al. (Cf. <g>απο-, δια-, επι-, παρα-, συμ-, παρα-, προ-</g>.)</s> </s>"},"G1080":{"l":"γεννάω","o":97,"ar":"<f><o>γεννάω</o>، <g>-ῶ</g> </f> <s> <s n=\"1.\">عن الأب، <b>يَلِد</b> (يُنجب): مع المنصوب، <r v=\"Matt.1.1-Matt.1.16\"></r>، <r v=\"Acts.7.8\"></r>، <r v=\"Acts.7.29\"></r>؛ يليه <g>ἐκ</g>، <r v=\"Matt.1.3\"></r>، <r v=\"Matt.1.5\"></r>، <r v=\"Matt.1.6\"></r>. </s> <s n=\"2.\">عن الأم، <b>تَلِد، تضع</b>: <r v=\"Luke.1.13\"></r>، <r v=\"Luke.1.57\"></r> <r v=\"Luke.23.29\"></r>، <r v=\"John.16.21\"></r>؛ <g>εἰς δουλείαν</g>، <r v=\"Gal.4.24\"></r>. المبني للمجهول <s n=\"(1)\"><b>يُحبَل به</b>، <b>يُولَد (من أب)</b>: <r v=\"Matt.1.20\"></r>؛ </s> <s n=\"(2)\"><b>يُولَد</b>: <r v=\"Matt.2.1\"></r>، <r v=\"Matt.2.4\"></r> <r v=\"Matt.19.12\"></r> <r v=\"Matt.26.24\"></r>، <r v=\"Mark.14.21\"></r>، <r v=\"Luke.1.35\"></r>، <r v=\"John.3.4\"></r>، <r v=\"Acts.7.20\"></r>، <r v=\"Rom.9.11\"></r>، <r v=\"Heb.11.23\"></r>؛ يليه <g>εἰς</g>، <r v=\"John.16.21\"></r> <r v=\"John.18.37\"></r>، <r v=\"2Pet.2.12\"></r>؛ <g>ἐν</g>، <r v=\"Acts.2.8\"></r> <r v=\"Acts.22.3\"></r>، (<g>ἁμαρτίαις</g>)، <r v=\"John.9.34\"></r>؛ <g>ἀπό</g>، <r v=\"Heb.11.12\"></r>؛ <g>ἐκ</g>، <r v=\"John.1.13\"></r> <r v=\"John.3.6\"></r> <r v=\"John.8.41\"></r>؛ مع صفة، <g>τυφλὸς γ.</g>، <r v=\"John.9.2\"></r>؛ <g>Ῥωμαῖος</g>، <r v=\"Acts.22.28\"></r>؛ <g>κατὰ σάρκα: κ. πνεῦμα</g>: <r v=\"Gal.4.29\"></r>. مجازيًا؛ <g>μάχας</g>، <r v=\"2Tim.2.23\"></r>؛ <g>ὑμᾶς ἐγέννησα</g>، <r v=\"1Cor.4.15\"></r>، (<g>ὅν</g>)، فليمون 10؛ في الاقتباس، <r v=\"Ps.2.7\"></r> (السبعينية)، <r v=\"Acts.13.33\"></r>، <r v=\"Heb.1.5\"></r> <r v=\"Heb.5.5\"></r>؛ عن المسيحيين بوصفهم مولودين من الله، مولودين ثانيةً: <r v=\"John.1.13\"></r> <r v=\"John.3.3\"></r>، <r v=\"John.3.5-John.3.8\"></r>، <r v=\"1John.2.29\"></r> <r v=\"1John.3.9\"></r> <r v=\"1John.4.7\"></r> <r v=\"1John.5.1\"></r>، <r v=\"1John.5.4\"></r>، <r v=\"1John.5.18\"></r> (قارن <g>ἀνα-γεννάω</g>).</s> </s> </s>","en":"<f><o>γεννάω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γέννα</g>, poët. for <g>γένος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3205\">ילד</h> ;]</e> </et> <s> <s n=\"1.\">of the father, <b>to beget</b>: c. acc., <r v=\"Matt.1.1-Matt.1.16\"></r>, <r v=\"Acts.7.8\"></r>, <r v=\"Acts.7.29\"></r>; seq. <g>ἐκ</g>, <r v=\"Matt.1.3\"></r>, <r v=\"Matt.1.5\"></r>, <r v=\"Matt.1.6\"></r>. </s> <s n=\"2.\">Of the mother, <b>to bring forth, bear</b>: <r v=\"Luke.1.13\"></r>, <r v=\"Luke.1.57\"></r> <r v=\"Luke.23.29\"></r>, <r v=\"John.16.21\"></r>; <g>εἰς δουλείαν</g>, <r v=\"Gal.4.24\"></r>. Pass. <s n=\"(1)\"><b>to be begotten</b>: <r v=\"Matt.1.20\"></r>; </s> <s n=\"(2)\"><b>to be born</b>: <r v=\"Matt.2.1\"></r>, <r v=\"Matt.2.4\"></r> <r v=\"Matt.19.12\"></r> <r v=\"Matt.26.24\"></r>, <r v=\"Mark.14.21\"></r>, <r v=\"Luke.1.35\"></r>, <r v=\"John.3.4\"></r>, <r v=\"Acts.7.20\"></r>, <r v=\"Rom.9.11\"></r>, <r v=\"Heb.11.23\"></r>; seq. <g>εἰς</g>, <r v=\"John.16.21\"></r> <r v=\"John.18.37\"></r>, <r v=\"2Pet.2.12\"></r>; <g>ἐν</g>, <r v=\"Acts.2.8\"></r> <r v=\"Acts.22.3\"></r>, (<g>ἁμαρτίαις</g>), <r v=\"John.9.34\"></r>; <g>ἀπό</g>, <r v=\"Heb.11.12\"></r> (WH, mg., <g>ἐγεν-</g>); <g>ἐκ</g>, <r v=\"John.1.13\"></r> <r v=\"John.3.6\"></r> <r v=\"John.8.41\"></r>; c. adj., <g>τυφλὸς γ.</g>, <r v=\"John.9.2\"></r>; [<g>Ῥωμαῖος</g> ], <r v=\"Acts.22.28\"></r>; <g>κατὰ σάρκα: κ. πνεῦμα</g>: <r v=\"Gal.4.29\"></r>. Metaph.; <g>μάχας</g>, <r v=\"2Tim.2.23\"></r>; <g>ὑμᾶς ἐγέννησα</g>, <r v=\"1Cor.4.15\"></r>, (<g>ὅν</g>), Phm 10; in quotation, <r v=\"Ps.2.7\"></r> (LXX), <r v=\"Acts.13.33\"></r>, <r v=\"Heb.1.5\"></r> <r v=\"Heb.5.5\"></r>; of Christians as begotten of God, born again: <r v=\"John.1.13\"></r> <r v=\"John.3.3\"></r>, <r v=\"John.3.5-John.3.8\"></r>, <r v=\"1John.2.29\"></r> <r v=\"1John.3.9\"></r> <r v=\"1John.4.7\"></r> <r v=\"1John.5.1\"></r>, <r v=\"1John.5.4\"></r>, <r v=\"1John.5.18\"></r> (cf. <g>ἀνα-γεννάω</g>); (Cremer, 146).</s> </s> </s>"},"G1014":{"l":"βούλομαι","o":37,"ar":"<f><o>βούλομαι</o>، </f> <s><b>أراد، رغب، اشتهى، قصد، عزم</b>، ويدل أقوى من <g>θέλω</g> (انظره) على ممارسة الإرادة عن تروٍّ (انظر التعليق على <r v=\"Jas.1.18\"></r>): مع المصدر: <r v=\"Mark.15.15\"></r>، <r v=\"Acts.5.28\"></r>، <r v=\"Acts.5.33\"></r>، <r v=\"Acts.12.4\"></r>، <r v=\"Acts.15.37\"></r>، <r v=\"Acts.17.20\"></r>، <r v=\"Acts.18.15\"></r>، <r v=\"Acts.15.27\"></r>، <r v=\"Acts.19.30\"></r>، <r v=\"Acts.22.30\"></r>، <r v=\"Acts.23.28\"></r>، <r v=\"Acts.27.43\"></r>، <r v=\"Acts.28.18\"></r>، <r v=\"2Cor.1.15\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"Heb.6.17\"></r>، <r v=\"2John.1.12\"></r>، <r v=\"3John.1.10\"></r>، <r v=\"Jude.1.5\"></r>؛ مع المنصوب: <r v=\"2Cor.1.17\"></r>؛ مع المنصوب والمصدر: <r v=\"Phil.1.12\"></r>، <r v=\"1Tim.2.8\"></r>، <r v=\"1Tim.5.14\"></r>، <r v=\"Titus.3.8\"></r>، <r v=\"2Pet.3.9\"></r>؛ عن الإرادة حين تختار بين أمرين: <r v=\"Matt.1.19\"></r>، <r v=\"Matt.11.27\"></r>، <r v=\"Luke.10.22\"></r>، <r v=\"Acts.25.20\"></r>، <r v=\"1Cor.12.11\"></r>، <r v=\"Jas.3.4\"></r>، <r v=\"Jas.4.4\"></r>؛ <g>εἰ βούλει</g> (عبارة مهذبة = <g>θέλεις</g> في اللغة الدارجة): <r v=\"Luke.22.4\"></r>؛ مع صيغة الاحتمال، تقويةً لسؤال التروّي: <r v=\"John.18.39\"></r>؛ <g>βουληθείς</g>: <i>عن قصد، بمشيئته</i>: <r v=\"Jas.1.18\"></r>؛ الماضي الناقص <g>ἐβουλόμην</g> (= <g>βουλοίμην ἄν</g>): <r v=\"Acts.25.22\"></r>، <r v=\"Phlm.1.13\"></r>.†</s>","en":"<f><o>βούλομαι</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2654\">חפץ</h>, <h n=\"H14\">אבה</h>, <h n=\"H3289\">יעץ</h>, etc. ;]</e> </et> <s><b>to will, wish, desire, purpose, be minded</b>, implying more strongly than <g>θέλω</g> (q.v.), the deliberate exercise of volition (v. Hort on <r v=\"Jas.1.18\"></r>): c. inf. (M, <i>Pr.</i>, 205; Bl., §69, 4), <r v=\"Mark.15.15\"></r>, <r v=\"Acts.5.28\"></r>, <r v=\"Acts.5.33\"></r> <r v=\"Acts.12.4\"></r> <r v=\"Acts.15.37\"></r> <r v=\"Acts.17.20\"></r> <r v=\"Acts.18.15\"></r>, <r v=\"Acts.15.27\"></r> <r v=\"Acts.19.30\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.23.28\"></r> <r v=\"Acts.27.43\"></r> <r v=\"Acts.28.18\"></r>, <r v=\"2Cor.1.15\"></r>, <r v=\"1Tim.6.9\"></r>, <r v=\"Heb.6.17\"></r>, <r v=\"2John.1.12\"></r>, <r v=\"3John.1.10\"></r>, <r v=\"Jude.1.5\"></r>; c. acc., <r v=\"2Cor.1.17\"></r>; c. acc. et inf., <r v=\"Phil.1.12\"></r>, <r v=\"1Tim.2.8\"></r> <r v=\"1Tim.5.14\"></r>, <r v=\"Titus.3.8\"></r>, <r v=\"2Pet.3.9\"></r>; of the will making choice between alternatives, <r v=\"Matt.1.19\"></r> <r v=\"Matt.11.27\"></r>, <r v=\"Luke.10.22\"></r>, <r v=\"Acts.25.20\"></r>, <r v=\"1Cor.12.11\"></r>, <r v=\"Jas.3.4\"></r> <r v=\"Jas.4.4\"></r>; <g>εἰ βούλει</g> (cl., a courteous phrase = <g>θέλεις</g>, colloq.; Bl., §21, 8; LS, s.v.), <r v=\"Luke.22.4\"></r>; c. subjc., adding force to a question of deliberation (Bl., §64, 6), <r v=\"John.18.39\"></r>; <g>βουληθείς</g>, <i>of set purpose</i> (v. Hort, in l.), <r v=\"Jas.1.18\"></r>; impf., <g>ἐβουλόμην</g> (= cl. <g>βουλοίμην ἄν</g>; Bl., §63, 5; Lft., <i>Phm.</i> 13), <r v=\"Acts.25.22\"></r>, <r v=\"Phlm.1.13\"></r> (v. also Cremer, 143).†</s>"},"G1065":{"l":"γέ","o":12,"ar":"<f><o>γε</o>، أداة ملحقة تأتي بعد الكلمة، تُبرز الكلمة التي تلحق بها إبرازًا خاصًا، فتميّزها بوصفها الأقل أو الأهم، </f> <s><b>حقًّا، على الأقل، حتى</b> (لكن لا يمكن دائمًا ترجمتها)؛ <s n=\"1.\">مستعملة وحدها: <r v=\"Luke.11.8\"></r> <r v=\"Luke.18.5\"></r> <r v=\"Rom.8.32\"></r>. </s> <s n=\"2.\">وأكثر شيوعًا مع أدوات أخرى: <g>αλλά γε</g>، <r v=\"Luke.24.21\"></r>، <r v=\"1Cor.9.2\"></r>؛ <g>ἄρα γε</g>، <r v=\"Matt.7.20\"></r> <r v=\"Matt.17.26\"></r>، <r v=\"Acts.17.27\"></r>؛ <g>ἆρά γε</g>، <r v=\"Acts.8.30\"></r>؛ <g>εἴ γε</g>، <r v=\"2Cor.5.3\"></r>، <r v=\"Gal.3.4\"></r>، <r v=\"Eph.3.2\"></r> <r v=\"Eph.4.21\"></r>، <r v=\"Col.1.23\"></r>؛ <g>εἰ δὲ μήγε</g>، بعد إثبات، <r v=\"Matt.6.1\"></r>، <r v=\"Luke.10.6\"></r> <r v=\"Luke.13.9\"></r>؛ وبعد نفي، <r v=\"Matt.9.17\"></r>، <r v=\"Luke.5.36\"></r>، <r v=\"Luke.5.37\"></r> <r v=\"Luke.14.32\"></r>، <r v=\"2Cor.11.16\"></r>؛ <g>καί γε</g>، <r v=\"Luke.19.42\"></r>، <r v=\"Acts.2.18\"></r> <r v=\"Acts.17.27\"></r>؛ <g>καίτοιγε</g>، <r v=\"John.4.2\"></r>؛ <g>μενοῦνγε</g> (انظر تحت المدخل)؛ <g>μήτι γε</g>، انظر تحت مدخل <g>μήτι</g>؛ <g>ὄφελόν</g>، <r v=\"1Cor.4.8\"></r>.†</s> </s>","en":"<f><o>γε</o>, enclitic postpositive particle, rarer in <g>κοινή</g> than in cl., giving special prominence to the word to which it is attached, distinguishing it as the least or the most important (Thayer, s.v.), </f> <s><b>indeed, at least, even</b> (but not always translatable into English); <s n=\"1.\">used alone: <r v=\"Luke.11.8\"></r> <r v=\"Luke.18.5\"></r> <r v=\"Rom.8.32\"></r>. </s> <s n=\"2.\">More freq. with other particles: <g>αλλά γε</g>, <r v=\"Luke.24.21\"></r>, <r v=\"1Cor.9.2\"></r>; <g>ἄρα γε</g>, <r v=\"Matt.7.20\"></r> <r v=\"Matt.17.26\"></r>, <r v=\"Acts.17.27\"></r>; <g>ἆρά γε</g>, <r v=\"Acts.8.30\"></r>; <g>εἴ γε</g> (Rec. <g>εἴγε</g>), <r v=\"2Cor.5.3\"></r>, <r v=\"Gal.3.4\"></r>, <r v=\"Eph.3.2\"></r> <r v=\"Eph.4.21\"></r>, <r v=\"Col.1.23\"></r> (v. Meyer, Ellic., on Ga, Eph, ll. c.; Lft., on Ga, Col, ll. c.); <g>εἰ δὲ μήγε</g>, following an affirmation, <r v=\"Matt.6.1\"></r>, <r v=\"Luke.10.6\"></r> <r v=\"Luke.13.9\"></r>; a negation, <r v=\"Matt.9.17\"></r>, <r v=\"Luke.5.36\"></r>, <r v=\"Luke.5.37\"></r> <r v=\"Luke.14.32\"></r>, <r v=\"2Cor.11.16\"></r>; <g>καί γε</g> (Rec. <g>καίγε</g>, cl. <g>καὶ . . . γε</g>), <r v=\"Luke.19.42\"></r> (WH om.), <r v=\"Acts.2.18\"></r> <r v=\"Acts.17.27\"></r>; <g>καίτοιγε</g> (L <g>καίτοι γε</g>, Tr. <g>καί τοι γε</g>), <r v=\"John.4.2\"></r>; <g>μενοῦνγε</g> (v. s.v.); <g>μήτι γε</g>, v.s. <g>μήτι</g>; <g>ὄφελόν</g>, <r v=\"1Cor.4.8\"></r>.†</s> </s>"},"G1093":{"l":"γῆ","o":275,"ar":"<f><o>γῆ</o>، <g>γῆς, ἡ</g>،</f> <s n=\"1.\"><b>الأرض</b>، <b>العالم</b>: <r v=\"Luke.21.35\"></r>، <r v=\"Acts.1.8\"></r>، <r v=\"Heb.11.13\"></r>، <r v=\"Rev.3.10\"></r>، وفي مواضع أخرى؛ عكس <g>οὐρανός</g>، <r v=\"Matt.5.18\"></r> <r v=\"Matt.11.25\"></r>، <r v=\"Mark.13.27\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>أرض (يابسة)</b>؛ <s n=\"(a)\">عكس البحر أو الماء: <r v=\"Mark.4.1\"></r>، <r v=\"Luke.5.3\"></r>، <r v=\"John.6.21\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">بوصفها أرضًا تُزرَع: <r v=\"Matt.13.5\"></r>، <r v=\"Mark.4.8\"></r>، <r v=\"Luke.13.7\"></r>، <r v=\"Heb.6.7\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(c)\"><b>التراب (سطح الأرض)</b>: <r v=\"Matt.10.29\"></r>، <r v=\"Mark.8.6\"></r>، <r v=\"Luke.24.5\"></r>، <r v=\"John.8.6\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(d)\"><b>إقليم</b>، <b>بلد</b>: <r v=\"Luke.4.25\"></r>، <r v=\"Rom.9.28\"></r>، <r v=\"Jas.5.17\"></r>؛ <g>γῆ Ἰσραήλ</g>، <r v=\"Matt.2.20\"></r>، <r v=\"Matt.2.21\"></r>؛ <g>Χαλδαίων</g>، <r v=\"Acts.7.4\"></r>؛ <g>ἡ Ἰουδαία γῆ</g>، <r v=\"John.3.22\"></r>؛ مع المضاف إليه الشخصي، <r v=\"Acts.7.3\"></r>.</s> </s>","en":"<f><o>γῆ</o>, <g>γῆς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H776\">אֶרֶץ</h>, <h n=\"H127\">אֲדָמָה</h>, etc.;]</e> </et> <s n=\"1.\"><b>the earth</b>, <b>world</b>: <r v=\"Luke.21.35\"></r>, <r v=\"Acts.1.8\"></r>, <r v=\"Heb.11.13\"></r>, <r v=\"Rev.3.10\"></r>, al.; opp. to <g>οὐρανός</g>, <r v=\"Matt.5.18\"></r> <r v=\"Matt.11.25\"></r>, <r v=\"Mark.13.27\"></r>, al. </s> <s n=\"2.\"><b>land</b>; <s n=\"(a)\">opp. to sea or water: <r v=\"Mark.4.1\"></r>, <r v=\"Luke.5.3\"></r>, <r v=\"John.6.21\"></r>, al.; </s> <s n=\"(b)\">as subject to cultivation: <r v=\"Matt.13.5\"></r>, <r v=\"Mark.4.8\"></r>, <r v=\"Luke.13.7\"></r>, <r v=\"Heb.6.7\"></r>, al.; </s> <s n=\"(c)\"><b>the ground</b>: <r v=\"Matt.10.29\"></r>, <r v=\"Mark.8.6\"></r>, <r v=\"Luke.24.5\"></r>, <r v=\"John.8.6\"></r>, al.; </s> <s n=\"(d)\"><b>a region</b>, <b>country</b>: <r v=\"Luke.4.25\"></r>, <r v=\"Rom.9.28\"></r>, <r v=\"Jas.5.17\"></r>; <g>γῆ Ἰσραήλ</g>, <r v=\"Matt.2.20\"></r>, <r v=\"Matt.2.21\"></r>; <g>Χαλδαίων</g>, <r v=\"Acts.7.4\"></r>; <g>ἡ Ἰουδαία γῆ</g>, <r v=\"John.3.22\"></r>; c. gen. pers., <r v=\"Acts.7.3\"></r>.</s> </s>"},"G1012":{"l":"βουλή","o":12,"ar":"<f><o>βουλή</o>، <g>-ῆς, ἡ</g> </f> <s><b>مشورة، قصد (رأي)</b>: <r v=\"Luke.23.51\"></r>، <r v=\"Acts.4.28\"></r> <r v=\"Acts.5.38\"></r> <r v=\"Acts.19.1\"></r> <r v=\"Acts.27.12\"></r>، <r v=\"Acts.27.42\"></r>؛ جمع، <r v=\"1Cor.4.5\"></r>؛ عن القصد الإلهي، <r v=\"Heb.6.17\"></r>؛ <g>τ. βουλὴν τ. θελήματος αὐτοῦ</g>، <r v=\"Eph.1.11\"></r>؛ <g>β. τ. Θεοῦ</g>، <r v=\"Luke.7.30\"></r>، <r v=\"Acts.2.23\"></r> <r v=\"Acts.13.36\"></r> <r v=\"Acts.20.27\"></r>.†</s>","en":"<f><o>βουλή</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βούλομαι</g>), </e> <e t=\"septuagint\">[in LXX freq. for <h n=\"H6098\">עֵצָה</h> ;]</e> </et> <s><b>counsel, purpose</b> (in cl., esp. of the gods): <r v=\"Luke.23.51\"></r>, <r v=\"Acts.4.28\"></r> <r v=\"Acts.5.38\"></r> <r v=\"Acts.19.1\"></r> <r v=\"Acts.27.12\"></r>, <r v=\"Acts.27.42\"></r>; pl., <r v=\"1Cor.4.5\"></r>; of the Divine purpose, <r v=\"Heb.6.17\"></r>; <g>τ. βουλὴν τ. θελήματος αὐτοῦ</g>, <r v=\"Eph.1.11\"></r>; <g>β. τ. Θεοῦ</g>, <r v=\"Luke.7.30\"></r>, <r v=\"Acts.2.23\"></r> <r v=\"Acts.13.36\"></r> <r v=\"Acts.20.27\"></r>.†</s>"},"G1074":{"l":"γενεά","o":43,"ar":"<f><o>γενεά</o>، <g>-ᾶς, ἡ</g> </f> <s> <s n=\"1.\"><b>جنس، سلالة، عائلة</b> (وفي العهد الجديد <g>γέννημα</g>، انظره). </s> <s n=\"2.\"><b>جيل</b>؛ <s n=\"(a)\">عن أفراد العائلة المتعاصرين: جمع، <r v=\"Matt.1.17\"></r> (قارن <r v=\"Gen.31.3\"></r>، <h n=\"H4138\">מוֹלֶדֶת</h>)؛ مجازيًا، عن المتشابهين في الطبع، بالمعنى السيئ، <r v=\"Matt.17.17\"></r>، <r v=\"Mark.9.19\"></r>، <r v=\"Luke.9.41\"></r> <r v=\"Luke.16.8\"></r>، <r v=\"Acts.2.40\"></r>؛ </s> <s n=\"(b)\">عن كل الناس في فترة معيّنة: <r v=\"Matt.24.34\"></r>، <r v=\"Mark.13.30\"></r>، <r v=\"Luke.21.32\"></r>، <r v=\"Phil.2.15\"></r>؛ جمع، <r v=\"Luke.1.48\"></r>؛ خاصةً عن الشعب اليهودي، <r v=\"Matt.11.16\"></r> <r v=\"Matt.12.39\"></r>، <r v=\"Matt.12.41\"></r>، <r v=\"Matt.12.42\"></r>، <r v=\"Matt.12.45\"></r> <r v=\"Matt.16.4\"></r> <r v=\"Matt.23.36\"></r>، <r v=\"Mark.8.12\"></r>، <r v=\"Mark.8.38\"></r> <r v=\"Luke.7.31\"></r> <r v=\"Luke.11.29\"></r>، <r v=\"Luke.11.30-Luke.11.32\"></r>، <r v=\"Luke.11.50\"></r>، <r v=\"Luke.11.51\"></r> <r v=\"Luke.17.25\"></r>، <r v=\"Acts.13.36\"></r>، <r v=\"Heb.3.10\"></r> <i>(السبعينية)</i>؛ <g>τὴν γ. αὐτοῦ τίς διηγήσεται</g>، <r v=\"Acts.8.33\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(c)\">المدة التي يغطيها عمر جيل واحد، وتُستعمل بالجمع استعمالاً فضفاضًا للعصور المتعاقبة: <r v=\"Acts.14.16\"></r> <r v=\"Acts.15.21\"></r>، <r v=\"Eph.3.5\"></r>، <r v=\"Col.1.26\"></r>؛ <g>εἰς γενεὰς καὶ γ.</g> (= <h n=\"H1755\">לִדוֹר וָדוֹר</h>، وفي مواضع أخرى)، <r v=\"Luke.34.17\"></r>، وفي مواضع أخرى)، <r v=\"Luke.1.50\"></r>؛ <g>εἰς πάσας τὰς γ. τοῦ αἰῶνος τῶν αἰώνων</g>، <r v=\"Eph.3.21\"></r>.</s> †</s> </s>","en":"<f><o>γενεά</o>, <g>-ᾶς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γίγνομαι</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1755\">דּוֹר</h>, <h n=\"H1755\">דֹּר</h> (Cremer, 148) ;]</e> </et> <s> <s n=\"1.\"><b>race, stock, family</b> (in NT, <g>γέννημα</g>, q.v.). </s> <s n=\"2.\"><b>generation</b>; <s n=\"(a)\">of the contemporary members of a family: pl., <r v=\"Matt.1.17\"></r> (cf. <r v=\"Gen.31.3\"></r>, <h n=\"H4138\">מוֹלֶדֶת</h>); metaph., of those alike in character, in bad sense, <r v=\"Matt.17.17\"></r>, <r v=\"Mark.9.19\"></r>, <r v=\"Luke.9.41\"></r> <r v=\"Luke.16.8\"></r>, <r v=\"Acts.2.40\"></r>; </s> <s n=\"(b)\">of all the people of a given period: <r v=\"Matt.24.34\"></r>, <r v=\"Mark.13.30\"></r>, <r v=\"Luke.21.32\"></r>, <r v=\"Phil.2.15\"></r>; pl., <r v=\"Luke.1.48\"></r>; esp. of the Jewish people, <r v=\"Matt.11.16\"></r> <r v=\"Matt.12.39\"></r>, <r v=\"Matt.12.41\"></r>, <r v=\"Matt.12.42\"></r>, <r v=\"Matt.12.45\"></r> <r v=\"Matt.16.4\"></r> <r v=\"Matt.23.36\"></r>, <r v=\"Mark.8.12\"></r>, <r v=\"Mark.8.38\"></r> <r v=\"Luke.7.31\"></r> <r v=\"Luke.11.29\"></r>, <r v=\"Luke.11.30-Luke.11.32\"></r>, <r v=\"Luke.11.50\"></r>, <r v=\"Luke.11.51\"></r> <r v=\"Luke.17.25\"></r>, <r v=\"Acts.13.36\"></r>, <r v=\"Heb.3.10\"></r> <i>(LXX)</i>; <g>τὴν γ. αὐτοῦ τίς διηγήσεται</g>, <r v=\"Acts.8.33\"></r> <i>(LXX)</i>; </s> <s n=\"(c)\">the period covered by the life-time of a generation, used loosely in pl. of successive ages: <r v=\"Acts.14.16\"></r> <r v=\"Acts.15.21\"></r>, <r v=\"Eph.3.5\"></r>, <r v=\"Col.1.26\"></r>; <g>εἰς γενεὰς καὶ γ.</g> (= <h n=\"H1755\">לִדוֹר וָדוֹר</h>, al.), <r v=\"Luke.34.17\"></r>, al), <r v=\"Luke.1.50\"></r>; <g>εἰς πάσας τὰς γ. τοῦ αἰῶνος τῶν αἰώνων</g>, <r v=\"Eph.3.21\"></r> (Ellic, in l.; <i>DCG</i>, i, 639f.).</s> †</s> </s>"},"G1097":{"l":"γινώσκω","o":220,"ar":"<f><o>γινώσκω</o>، </f> <s><b>يكتسب معرفة، يتعرّف على، يعرف (يتبيّن)، يدرك، يفهم</b>؛ وفي الأزمنة الماضية <b>يعرف، يعي</b>؛ المبني للمجهول، <b>يصير معروفًا</b>: مع المنصوب، <r v=\"Matt.22.18\"></r>، <r v=\"Mark.5.43\"></r>، <r v=\"Col.4.8\"></r>، <r v=\"1Thess.3.5\"></r>، وفي مواضع أخرى. المبني للمجهول، <r v=\"Matt.10.26\"></r>، <r v=\"Phil.4.5\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Matt.21.45\"></r>، <r v=\"John.4.1\"></r>، وفي مواضع أخرى؛ <g>τί</g>، <r v=\"Matt.6.3\"></r>؛ <g>ἀπό</g>، <r v=\"Mark.15.45\"></r>؛ <g>ὅ</g>، <r v=\"Rom.7.15\"></r>؛ <g>τ. λεγόμενα</g>، <r v=\"Luke.18.34\"></r>؛ <g>τ. θέλημα</g>، <r v=\"Luke.12.47\"></r>؛ <g>τ. καρδίας</g>، <r v=\"Luke.16.15\"></r>؛ مع منصوب الشخص، عن معرفة الله للإنسان (اعترافه به)، <r v=\"1Cor.8.3\"></r>، <r v=\"Gal.4.9\"></r>؛ ومن المسيح، منفيًّا، <r v=\"Matt.7.23\"></r>؛ وكثيرًا عن معرفة الأمور الإلهية، معرفة الله والمسيح؛ <g>τ. θεόν</g>، <r v=\"Rom.1.21\"></r> <r v=\"Gal.4.9\"></r>؛ <g>τ. πατέρα</g>، <r v=\"John.8.55\"></r>؛ <g>τ. κύριον</g>، <r v=\"Heb.8.1\"></r> <i>(السبعينية)</i>؛ <g>νοῦν κυρίου</g>، <r v=\"Rom.11.34\"></r>؛ <g>Χριστόν</g>، <r v=\"John.17.3\"></r>، <r v=\"1John.3.6\"></r>؛ <g>τὰ τοῦ πνεύματος</g>، <r v=\"1Cor.2.14\"></r>؛ <g>τ. πνεύμα</g>، <r v=\"1John.4.6\"></r>؛ <g>τ. ἀλήθειαν</g>، <r v=\"John.8.32\"></r>؛ عن معرفة المسيح للآب (<g>ἐπιγ.</g>)، <r v=\"Matt.11.27\"></r> . وعند الكتّاب الهلنستيين [في السبعينية ترجمةً للعبرية <h n=\"H3045\">ידע</h>، <r v=\"Gal.4.1\"></r>، وفي مواضع أخرى]، عن العلاقة الجنسية، <b>يعرف</b> معرفةً جسدية: <r v=\"Matt.1.25\"></r>، <r v=\"Luke.1.34\"></r> .</s>","en":"<f><o>γινώσκω</o> (= <g>γιγν-</g>: v. previous word. So also vulgar Attic, in Inscr., v. Thumb, <i>MGV</i>, 207), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3045\">ידע</h> ;]</e> </et> <s><b>to be taking in knowledge, come to know, recognize, perceive, understand</b>; in past tenses <b>to know, realize</b>; pass., <b>to become known</b>: c. acc., <r v=\"Matt.22.18\"></r>, <r v=\"Mark.5.43\"></r>, <r v=\"Col.4.8\"></r>, <r v=\"1Thess.3.5\"></r>, al. Pass., <r v=\"Matt.10.26\"></r>, <r v=\"Phil.4.5\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Matt.21.45\"></r>, <r v=\"John.4.1\"></r>, al.; <g>τί</g>, <r v=\"Matt.6.3\"></r>; <g>ἀπό</g>, <r v=\"Mark.15.45\"></r>; <g>ὅ</g>, <r v=\"Rom.7.15\"></r>; <g>τ. λεγόμενα</g>, <r v=\"Luke.18.34\"></r>; <g>τ. θέλημα</g>, <r v=\"Luke.12.47\"></r>; <g>τ. καρδίας</g>, <r v=\"Luke.16.15\"></r>; c acc. pers., of recognition by God, <r v=\"1Cor.8.3\"></r>, <r v=\"Gal.4.9\"></r>; by Christ, neg., <r v=\"Matt.7.23\"></r>; freq. of the knowledge of divine things, of God and Christ; <g>τ. θεόν</g>, <r v=\"Rom.1.21\"></r> <r v=\"Gal.4.9\"></r>; <g>τ. πατέρα</g>, <r v=\"John.8.55\"></r>; <g>τ. κύριον</g>, <r v=\"Heb.8.1\"></r> <i>(LXX)</i>; <g>νοῦν κυρίου</g>, <r v=\"Rom.11.34\"></r>; <g>Χριστόν</g>, <r v=\"John.17.3\"></r>, <r v=\"1John.3.6\"></r>; <g>τὰ τοῦ πνεύματος</g>, <r v=\"1Cor.2.14\"></r>; <g>τ. πνεύμα</g>, <r v=\"1John.4.6\"></r>; <g>τ. ἀλήθειαν</g>, <r v=\"John.8.32\"></r>; of Christ's knowledge of the Father (<g>ἐπιγ.</g>), <r v=\"Matt.11.27\"></r> (Dalman, <i>Words</i>, 282ff.). In Hellenistic writers [LXX for Heb. <h n=\"H3045\">ידע</h>, <r v=\"Gal.4.1\"></r>, al.], of sexual intercourse, <b>to know</b> carnally: <r v=\"Matt.1.25\"></r>, <r v=\"Luke.1.34\"></r> (Cremer, 153).</s> <sy><i>SYN.</i>: <g>γ.</g>, <b>to know</b> by observation and experience is thus prop. disting. from <g>οἶδα</g>, to know by reflection (a mental process, based on intuition or information); cf. also <g>ἐφίστημι, συνίημι</g>. (Cf. <g>ἀνα-, δια-, ἐπι-, κατα-, προ-γινώσκω</g>.)</sy>"},"G1060":{"l":"γαμέω","o":28,"ar":"<f>* <o>γαμέω</o>، <g>-ῶ</g>، </f> <s><b>يتزوج</b>؛ <s n=\"1.\">عن الرجل: <b>يتزوج، يتخذ زوجة</b>: مطلقًا، <r v=\"Matt.19.10\"></r>، <r v=\"Matt.22.25\"></r>، <r v=\"Matt.22.30\"></r>، <r v=\"Matt.24.38\"></r>، <r v=\"Mark.12.25\"></r>، <r v=\"Luke.17.27\"></r>، <r v=\"Luke.20.34\"></r>، <r v=\"Luke.20.35\"></r>، <r v=\"1Cor.7.28\"></r>، <r v=\"1Cor.7.33\"></r>؛ مع المنصوب: <r v=\"Matt.5.32\"></r>، <r v=\"Matt.19.9\"></r>، <r v=\"Mark.6.17\"></r>، <r v=\"Mark.10.11\"></r>، <r v=\"Luke.14.20\"></r>، <r v=\"Luke.16.18\"></r>. </s> <s n=\"2.\">عن المرأة: <s n=\"(a)\">الصيغة الوسطى (والمبني للمجهول عند الكتّاب المتأخرين): <b>تُزَوَّج، تتزوج</b>: <r v=\"1Cor.7.39\"></r>؛ </s> <s n=\"(b)\">في اليونانية المتأخرة، المبني للمعلوم (كما عن الرجل): <b>تتزوج</b>: مطلقًا، <r v=\"1Cor.7.28\"></r>، <r v=\"1Cor.7.34\"></r>، <r v=\"1Tim.5.11\"></r>، <r v=\"1Tim.5.14\"></r>؛ مع المنصوب، <r v=\"Mark.10.12\"></r>. </s> </s> <s n=\"3.\">عن الجنسين: مطلقًا، <r v=\"1Tim.4.3\"></r>، <r v=\"1Cor.7.9\"></r>، <r v=\"1Cor.7.10\"></r>، <r v=\"1Cor.7.36\"></r>.†</s> </s>","en":"<f>* <o>γαμέω</o>, <g>-ῶ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Esth.10.3\"></r>, <r v=\"2Macc.14.25\"></r>, <r v=\"4Macc.16.9\"></r> * ;]</e> </et> <s><b>to marry</b>; <s n=\"1.\">of the man, <b>to marry, take to wife</b> (<l>ducere</l>): absol., <r v=\"Matt.19.10\"></r> <r v=\"Matt.22.25\"></r>, <r v=\"Matt.22.30\"></r> <r v=\"Matt.24.38\"></r>, <r v=\"Mark.12.25\"></r>, <r v=\"Luke.17.27\"></r>, <r v=\"Luke.20.34\"></r>, <r v=\"Luke.20.35\"></r>, <r v=\"1Cor.7.28\"></r>, <r v=\"1Cor.7.33\"></r>; c. acc.: <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.9\"></r>, <r v=\"Mark.6.17\"></r> <r v=\"Mark.10.11\"></r>, <r v=\"Luke.14.20\"></r> <r v=\"Luke.16.18\"></r>. </s> <s n=\"2.\">Of the woman, <s n=\"(a)\">mid. (and in late writers, pass.), <b>to give oneself in marriage, marry</b> (<l>nubere</l>): <r v=\"1Cor.7.39\"></r>; </s> <s n=\"(b)\">in Hellenistic (M, <i>Pr.</i>, 159), act. (as of the man), <b>to marry</b>: absol., <r v=\"1Cor.7.28\"></r>, <r v=\"1Cor.7.34\"></r>, <r v=\"1Tim.5.11\"></r>, <r v=\"1Tim.5.14\"></r>. c acc., <r v=\"Mark.10.12\"></r>. </s> </s> <s n=\"3.\">Of both sexes: absol., <r v=\"1Tim.4.3\"></r>, <r v=\"1Cor.7.9\"></r>, <r v=\"1Cor.7.10\"></r>, <r v=\"1Cor.7.36\"></r>.†</s> </s>"},"G1076":{"l":"γενεαλογία","o":2,"ar":"<f>* <o>γενεαλογία</o>، <g>-ας, ἡ</g>؛ </f> <s> <s n=\"1.\"><b>وضع سلسلة نسب</b>. </s> <s n=\"2.\"><b>سلسلة أنساب</b>: الجمع، <r v=\"1Tim.1.4\"></r>، <r v=\"Titus.3.9\"></r>.†</s></s>","en":"<f>* <o>γενεαλογία</o>, <g>-ας, ἡ</g> (v. previous word); </f> <s> <s n=\"1.\"><b>the making of a pedigree</b>. </s> <s n=\"2.\"><b>a genealogy</b>: pl., <r v=\"1Tim.1.4\"></r>, <r v=\"Titus.3.9\"></r> (v. <i>CGT</i>, in l., and ib. <i>Intr.</i>, xlix ff.; <i>DB</i>, ii, p. 141).†</s></s>"},"G1092":{"l":"γεωργός","o":19,"ar":"<f><o>γεωργός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\"><b>فلاّح، حارث</b>: <r v=\"2Tim.2.6\"></r>، <r v=\"Jas.5.7\"></r>.</s> <s n=\"2.\"><b>كرّام</b> (قارن <x><g>ἀμπελουργός</g></x>، <r v=\"Luke.13.7\"></r>): <r v=\"Matt.21.33-Matt.21.35\"></r>، <r v=\"Matt.21.38\"></r>، <r v=\"Matt.21.40\"></r>، <r v=\"Matt.21.41\"></r>، <r v=\"Mark.12.1\"></r>، <r v=\"Mark.12.2\"></r>، <r v=\"Mark.12.7\"></r>، <r v=\"Mark.12.9\"></r>، <r v=\"Luke.20.9\"></r>، <r v=\"Luke.20.10\"></r>، <r v=\"Luke.20.14\"></r>، <r v=\"Luke.20.16\"></r>، <r v=\"John.15.1\"></r>.†</s>","en":"<f><o>γεωργός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>γῆ</g></x>, <x><g>ἔργω</g></x> = <x><g>ἔρδω</g></x>, <i>to do</i>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H406\">אִכָּר</h>, etc.;]</e> </et> <s n=\"1.\"><b>a husbandman</b>: <r v=\"2Tim.2.6\"></r>, <r v=\"Jas.5.7\"></r>.</s> <s n=\"2.\"><b>a vine-dresser</b> (cf. <x><g>ἀμπελουργός</g></x>, <r v=\"Luke.13.7\"></r>): <r v=\"Matt.21.33-Matt.21.35\"></r>, <r v=\"Matt.21.38\"></r>, <r v=\"Matt.21.40\"></r>, <r v=\"Matt.21.41\"></r>, <r v=\"Mark.12.1\"></r>, <r v=\"Mark.12.2\"></r>, <r v=\"Mark.12.7\"></r>, <r v=\"Mark.12.9\"></r>, <r v=\"Luke.20.9\"></r>, <r v=\"Luke.20.10\"></r>, <r v=\"Luke.20.14\"></r>, <r v=\"Luke.20.16\"></r>, <r v=\"John.15.1\"></r>.†</s>"},"G1019":{"l":"βραδύνω","o":2,"ar":"<f><o>βραδύνω</o> </f> <s> <s n=\"1.\">متعدٍّ: <b>يؤخِّر</b> (في الكلاسيكية وفي إشعياء في السبعينية). </s> <s n=\"2.\">والأكثر لازم: <b>يبطئ، يتأخّر</b>: <r v=\"1Tim.3.15\"></r>، <r v=\"2Pet.3.9\"></r>.†</s> </s>","en":"<f><o>βραδύνω</o> </f> <et> <e t=\"derivation\">(&lt; <g>βραδύς</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.43.10\"></r> (<h n=\"H4102\">מההּ</h> hith.), <r v=\"Deut.7.10\"></r>, <r v=\"Isa.46.13\"></r> (<h n=\"H309\">אחר</h> pi.), <r v=\"Sir.32.18\"></r> * ;]</e> </et> <s> <s n=\"1.\">trans., <b>to retard</b> (Soph., Is, l.c.). </s> <s n=\"2.\">More freq. intrans., <b>to be slow, to tarry</b>: <r v=\"1Tim.3.15\"></r>, <r v=\"2Pet.3.9\"></r>.†</s> </s>"},"G1063":{"l":"γάρ","o":1041,"ar":"<f><o>γάρ</o>، </f> أداة ربط عطفية، مركّبة من <g>γε ἄρα</g>، <s><b>حقًّا إذن</b>، ومن ثم <b>في الحقيقة، حقًّا، نعم، إذن، فلماذا</b>، وعند ذكر سبب أو تفسير: <b>لأن، فإن</b>؛ <s n=\"1.\">تفسيريًّا وإيضاحيًّا: <r v=\"Matt.4.18\"></r>، <r v=\"Matt.19.12\"></r>، <r v=\"Mark.1.16\"></r>، <r v=\"Mark.5.42\"></r>، <r v=\"Mark.16.4\"></r>، <r v=\"Luke.11.30\"></r>، <r v=\"Rom.7.1\"></r>، <r v=\"1Cor.16.5\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\">استنتاجيًّا، في الأسئلة والأجوبة والتعجب: <r v=\"Matt.9.5\"></r>، <r v=\"Matt.27.23\"></r>، <r v=\"Luke.9.25\"></r>، <r v=\"Luke.22.27\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.8.31\"></r>، <r v=\"Acts.16.37\"></r>، <r v=\"Acts.19.35\"></r>، <r v=\"Rom.15.26\"></r>، <r v=\"1Cor.9.10\"></r>، <r v=\"Phil.1.18\"></r>، <r v=\"1Thess.2.20\"></r>، وفي مواضع أخرى. </s> <s n=\"3.\">سببيًّا: <r v=\"Matt.1.21\"></r>، <r v=\"Matt.2.2\"></r>، <r v=\"Matt.2.5\"></r>، <r v=\"Matt.2.6\"></r>، <r v=\"Matt.3.23\"></r>، <r v=\"Mark.1.22\"></r>، <r v=\"Mark.9.6\"></r>، <r v=\"Luke.1.15\"></r>، <r v=\"Luke.1.18\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Acts.2.25\"></r>، <r v=\"Rom.1.9\"></r>، <r v=\"Rom.1.11\"></r>، <r v=\"1Cor.11.5\"></r>، <r v=\"Rev.1.3\"></r>، وفي مواضع أخرى؛ في ذكر سبب أمر أو نهي: <r v=\"Matt.2.20\"></r>، <r v=\"Matt.3.9\"></r>، <r v=\"Rom.13.11\"></r>، <r v=\"Col.3.3\"></r>، <r v=\"1Thess.4.3\"></r>، وفي مواضع أخرى؛ حين يكون السبب في عبارة استفهامية: <r v=\"Luke.22.27\"></r>، <r v=\"Rom.3.3\"></r>، <r v=\"Rom.4.3\"></r>، <r v=\"1Cor.10.29\"></r>؛ <g>καὶ γάρ</g>: <b>لأنه أيضًا</b>: <r v=\"Mark.10.45\"></r>، <r v=\"Luke.6.32\"></r>، <r v=\"1Cor.5.7\"></r>، وفي مواضع أخرى؛ وكذلك بمعنى <l>etenim</l> (فإنه حقًّا)، حيث تفقد <g>καί</g> قوتها العاطفة: <r v=\"Mark.14.70\"></r>، <r v=\"Luke.1.66\"></r>، <r v=\"Luke.22.37\"></r>، <r v=\"1Cor.13.4\"></r>. وموضع <g>γάρ</g> الأصلي بعد الكلمة الأولى من الجملة، لكنها في الشعر كثيرًا ما تأتي ثالثة أو رابعة، وكذلك في النثر المتأخر: <r v=\"2Cor.1.19\"></r>.</s> </s>","en":"<f><o>γάρ</o>, </f> co-ordinating particle, contr. of <g>γε ἄρα</g>, <s><b>verily then</b>, hence, <b>in truth, indeed, yea, then, why</b>, and when giving a reason or explanation, <b>for</b>, the usage in NT being in general accord with that of cl.; <s n=\"1.\">explicative and epexegetic: <r v=\"Matt.4.18\"></r> <r v=\"Matt.19.12\"></r>, <r v=\"Mark.1.16\"></r> <r v=\"Mark.5.42\"></r> <r v=\"Mark.16.4\"></r>, <r v=\"Luke.11.30\"></r>, <r v=\"Rom.7.1\"></r>, <r v=\"1Cor.16.5\"></r>, al. </s> <s n=\"2.\">Conclusive, in questions, answers and exclamations: <r v=\"Matt.9.5\"></r> <r v=\"Matt.27.23\"></r>, <r v=\"Luke.9.25\"></r> <r v=\"Luke.22.27\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.8.31\"></r> <r v=\"Acts.16.37\"></r> <r v=\"Acts.19.35\"></r>, <r v=\"Rom.15.26\"></r>, <r v=\"1Cor.9.10\"></r>, <r v=\"Phil.1.18\"></r> (Ellic., in l.), <r v=\"1Thess.2.20\"></r>, al. </s> <s n=\"3.\">Causal: <r v=\"Matt.1.21\"></r> <r v=\"Matt.2.2\"></r>, <r v=\"Matt.2.5\"></r>, <r v=\"Matt.2.6\"></r>, <r v=\"Matt.3.23\"></r>, <r v=\"Mark.1.22\"></r>, <r v=\"Mark.9.6\"></r>, <r v=\"Luke.1.15\"></r>, <r v=\"Luke.1.18\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Acts.2.25\"></r>, <r v=\"Rom.1.9\"></r>, <r v=\"Rom.1.11\"></r>, <r v=\"1Cor.11.5\"></r>, <r v=\"Rev.1.3\"></r>, al.; giving the reason for a command or prohibition, <r v=\"Matt.2.20\"></r> <r v=\"Matt.3.9\"></r>, <r v=\"Rom.13.11\"></r>, <r v=\"Col.3.3\"></r>, <r v=\"1Thess.4.3\"></r>, al.; where the cause is contained in an interrog. statement, <r v=\"Luke.22.27\"></r>, <r v=\"Rom.3.3\"></r> <r v=\"Rom.4.3\"></r>, <r v=\"1Cor.10.29\"></r>; <g>καὶ γάρ</g>, <b>for also</b>, <r v=\"Mark.10.45\"></r>, <r v=\"Luke.6.32\"></r>, <r v=\"1Cor.5.7\"></r>, al. id. as in cl. = <l>etenim</l>, where the <g>καί</g> loses its connective force (Bl., §78, 6; Kühner 3, ii, 854f.), <r v=\"Mark.14.70\"></r>, <r v=\"Luke.1.66\"></r> <r v=\"Luke.22.37\"></r>, <r v=\"1Cor.13.4\"></r>. The proper place of <g>γάρ</g> is after the first word in a clause, but in poets it often comes third or fourth, and so in late prose: <r v=\"2Cor.1.19\"></r>. Yet \"not the number but the nature of the word after which it stands is the point to be noticed\" (v. Thayer, s.v.).</s> </s>"},"G1033":{"l":"βρῶμα","o":17,"ar":"<f><o>βρῶμα</o>، <g>-τος, τό</g> (قارن <g>βιβρώσκω</g>)، </f> <s><b>طعام</b>: <r v=\"Rom.14.15\"></r>، <r v=\"Rom.14.20\"></r>، <r v=\"1Cor.8.8\"></r>، <r v=\"1Cor.8.13\"></r>، <r v=\"1Cor.10.3\"></r>؛ في الجمع: <r v=\"Matt.14.15\"></r>، <r v=\"Mark.7.19\"></r>، <r v=\"Luke.3.11\"></r>، <r v=\"Luke.9.13\"></r>، <r v=\"1Cor.6.13\"></r>، <r v=\"1Tim.4.3\"></r>، <r v=\"Heb.9.10\"></r>، <r v=\"Heb.13.9\"></r>؛ مجازيًا، عن الطعام الروحي: <r v=\"John.4.34\"></r>، <r v=\"1Cor.3.2\"></r> (قارن <g>βρῶσις</g>).†</s>","en":"<f><o>βρῶμα</o>, <g>-τος, τό</g> (cf. <g>βιβρώσκω</g>), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H400\">אֹכֶל</h> ;]</e> </et> <s><b>food</b>: <r v=\"Rom.14.15\"></r>, <r v=\"Rom.14.20\"></r> <r v=\"1Cor.8.8\"></r>, <r v=\"1Cor.8.13\"></r> <r v=\"1Cor.10.3\"></r>; pl., <r v=\"Matt.14.15\"></r>, <r v=\"Mark.7.19\"></r>, <r v=\"Luke.3.11\"></r> <r v=\"Luke.9.13\"></r>, <r v=\"1Cor.6.13\"></r>, <r v=\"1Tim.4.3\"></r>, <r v=\"Heb.9.10\"></r> <r v=\"Heb.13.9\"></r>; trop., of spiritual food, <r v=\"John.4.34\"></r>, <r v=\"1Cor.3.2\"></r> (cf. <g>βρῶσις</g>).†</s>"},"G1089":{"l":"γεύω","o":15,"ar":"<f><o>γεύω</o>،</f> <s><b>جعله يذوق</b>. والصيغة الوسطى: <b>ذاق، أكل</b>: مطلقًا، <r v=\"Acts.10.10\"></r>، <r v=\"Acts.20.11\"></r>، <r v=\"Col.2.21\"></r>؛ مع المضاف إليه، <r v=\"Matt.27.34\"></r>، <r v=\"Luke.14.24\"></r>، <r v=\"Acts.23.14\"></r>؛ مع المنصوب (قارن <r v=\"Heb.2.9\"></r>)، <r v=\"John.2.9\"></r>. مجازيًا، <r v=\"Heb.6.4\"></r>؛ <g>ῥῆμα θεοῦ</g>، <r v=\"Heb.6.5\"></r>؛ <g>θανάτου</g> (قارن العبارة التلمودية <h n=\"H2938\">טַעַם מִיתָה</h>)، <r v=\"Matt.16.28\"></r>، <r v=\"Mark.9.1\"></r>، <r v=\"Luke.9.27\"></r>، <r v=\"John.8.52\"></r>، <r v=\"Heb.2.9\"></r>؛ يليه <g>ὅτι</g>، <r v=\"1Pet.2.3\"></r>.†</s>","en":"<f><o>γεύω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2938\">טעם</h>;]</e> </et> <s><b>to make to taste</b>. Mid., <b>to taste eat</b>: absol., <r v=\"Acts.10.10\"></r> <r v=\"Acts.20.11\"></r>, <r v=\"Col.2.21\"></r>; c. gen., <r v=\"Matt.27.34\"></r>, <r v=\"Luke.14.24\"></r>, <r v=\"Acts.23.14\"></r>; c. acc. (not cl., but v. Westc, <r v=\"Heb.2.9\"></r>; M, <i>Pr.</i>, 66, 245), <r v=\"John.2.9\"></r>. Metaph., <r v=\"Heb.6.4\"></r>; <g>ῥῆμα θεοῦ</g>, <r v=\"Heb.6.5\"></r> (on case, v. supr., and cf. Milligan, <i>NTD</i>, 68) <g>θανάτου</g> (cf. Talmudic <h n=\"H2938\">טַעַם מִיתָה</h>), <r v=\"Matt.16.28\"></r>, <r v=\"Mark.9.1\"></r>, <r v=\"Luke.9.27\"></r>, <r v=\"John.8.52\"></r>, <r v=\"Heb.2.9\"></r>; seq. <g>ὅτι</g>, <r v=\"1Pet.2.3\"></r> (Cremer, 148).†</s>"},"G1035":{"l":"βρῶσις","o":11,"ar":"<f><o>βρῶσις</o>، <g>-εως, ἡ</g> (قارن <g>βιβρώσκω</g>)، </f> <s> <s n=\"1.\"><b>أكل</b>: <g>β. καὶ πόσις</g>، <r v=\"Rom.14.17\"></r>، <r v=\"Col.2.16\"></r>؛ مع المضاف إليه المفعول، <r v=\"1Cor.8.4\"></r>؛ مجازيًا: <i>تآكُل، صدأ</i>: <r v=\"Matt.6.19\"></r>، <r v=\"Matt.16.20\"></r>. </s> <s n=\"2.\">وكما في اليونانية الكلاسيكية أيضًا = <g>βρῶμα</g>: <b>طعام</b>: <r v=\"John.6.27\"></r>، <r v=\"2Cor.9.10\"></r>، <r v=\"Col.2.16\"></r>. <r v=\"Heb.12.16\"></r>؛ مجازيًا، عن الغذاء الروحي، <r v=\"John.4.32\"></r>، <r v=\"John.6.27\"></r>، <r v=\"John.6.55\"></r>.†</s> </s>","en":"<f><o>βρῶσις</o>, <g>-εως, ἡ</g> (cf. <g>βιβρώσκω</g>), </f> <et> <e t=\"septuagint\">[in LXX chiefly for parts and derivatives of <h n=\"H398\">אכל</h> ;]</e> </et> <s> <s n=\"1.\"><b>eating</b>: <g>β. καὶ πόσις</g>, <r v=\"Rom.14.17\"></r>, <r v=\"Col.2.16\"></r> (v. Lft., <i>ICC</i>, in l.); c. gen. obj., <r v=\"1Cor.8.4\"></r>; metaph., <i>corrosion, rust</i>: <r v=\"Matt.6.19\"></r>, <r v=\"Matt.16.20\"></r>. </s> <s n=\"2.\">As also in cl. (Hom., al.) = <g>βρῶμα</g>, <b>food</b>: <r v=\"John.6.27\"></r>, <r v=\"2Cor.9.10\"></r>, <r v=\"Col.2.16\"></r> (EV, but v. supr.). <r v=\"Heb.12.16\"></r>; metaph., of spiritual nourishment, <r v=\"John.4.32\"></r> <r v=\"John.6.27\"></r>, <r v=\"John.6.55\"></r>.†</s> </s>"},"G1025":{"l":"βρέφος","o":8,"ar":"<f>** <o>βρέφος</o>، <g>-ους, τό</g>، </f> <s> <s n=\"1.\"><b>جنين</b>: <r v=\"Luke.1.41\"></r>، <r v=\"Luke.1.44\"></r>. </s> <s n=\"2.\"><b>طفل وليد، رضيع</b>: <r v=\"Luke.2.12\"></r>، <r v=\"Luke.2.16\"></r>، <r v=\"Luke.18.15\"></r>، <r v=\"Acts.7.19\"></r>، <r v=\"1Pet.2.2\"></r>؛ <g>ἀπὸ βρέφους</g>: <i>منذ الطفولة</i>، <r v=\"2Tim.3.15\"></r>.†</s> </s>","en":"<f>** <o>βρέφος</o>, <g>-ους, τό</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.19.11\"></r>, <r v=\"1Macc.1.61\"></r>, <r v=\"2Macc.6.10\"></r>, <r v=\"3Macc.5.49\"></r>, <r v=\"4Macc.4.25\"></r>*;]</e> </et> <s> <s n=\"1.\"><b>an unborn child</b>: <r v=\"Luke.1.41\"></r>, <r v=\"Luke.1.44\"></r>. </s> <s n=\"2.\"><b>a newborn child, a babe</b>: <r v=\"Luke.2.12\"></r>, <r v=\"Luke.2.16\"></r> <r v=\"Luke.18.15\"></r>, <r v=\"Acts.7.19\"></r>, <r v=\"1Pet.2.2\"></r>; <g>ἀπὸ βρέφους</g>, <i>from infancy</i>, <r v=\"2Tim.3.15\"></r>.†</s> </s>"},"G1053":{"l":"Γαλατία","o":4,"ar":"<f><o>Γαλατία</o>، <g>-ας, ἡ</g>، </f> <s><b>غلاطية</b>؛ <s n=\"1.\">إقليم في آسيا الصغرى سكنته قبائل الغال (القرن الثالث ق.م). </s> <s n=\"2.\">ولاية رومانية تشمل هذا الإقليم: <r v=\"1Cor.16.1\"></r>، <r v=\"Gal.1.2\"></r>، <r v=\"2Tim.4.10\"></r>، <r v=\"1Pet.1.1\"></r>.†</s> </s>","en":"<f><o>Γαλατία</o>, <g>-ας, ἡ</g>, </f> <s><b>Galatia</b>; <s n=\"1.\">a gentilic region in Asia Minor, settled by Gauls (iii/B.C). </s> <s n=\"2.\">A Roman Province which included this region (<i>DB</i>, ii, 85ff.): <r v=\"1Cor.16.1\"></r>, <r v=\"Gal.1.2\"></r>, <r v=\"2Tim.4.10\"></r> (T, Tr., mg., <g>Γαλλίαν</g>), <r v=\"1Pet.1.1\"></r>.†</s> </s>"},"G1085":{"l":"γένος","o":20,"ar":"<f><o>γένος</o>، <g>-ους, τό</g></f> <s n=\"1.\"><b>عائلة، عشيرة</b>: <r v=\"Acts.4.6\"></r> <r v=\"Acts.7.13\"></r> <r v=\"Acts.13.26\"></r>.</s> <s n=\"2.\"><b>نسل، ذرية</b>: <r v=\"Acts.17.28\"></r>، <r v=\"Acts.17.29\"></r>، <r v=\"Rev.22.16\"></r>.</s> <s n=\"3.\"><b>جنس</b>، <b>أمّة</b>؛ <r v=\"Mark.7.28\"></r>، <r v=\"Acts.4.36\"></r> <r v=\"Acts.7.19\"></r> <r v=\"Acts.18.2\"></r>، <r v=\"Acts.18.24\"></r>، <r v=\"2Cor.11.26\"></r>، <r v=\"Phil.3.5\"></r>، <r v=\"Gal.1.14\"></r>، <r v=\"1Pet.2.9\"></r>.</s> <s n=\"4.\"><b>نوع</b>، <b>صنف</b>، <b>فئة</b>: <r v=\"Matt.13.47\"></r> <r v=\"Matt.17.21\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"1Cor.12.10\"></r>، <r v=\"1Cor.12.28\"></r> <r v=\"1Cor.14.10\"></r>.†</s>","en":"<f><o>γένος</o>, <g>-ους, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>γίγνομαι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5971\">עַם</h>, <h n=\"H4327\">מִין</h>, <h n=\"H2233\">זֶרַע</h>, etc.;]</e> </et> <s n=\"1.\"><b>family</b>: <r v=\"Acts.4.6\"></r> <r v=\"Acts.7.13\"></r> <r v=\"Acts.13.26\"></r>.</s> <s n=\"2.\"><b>offspring</b>: <r v=\"Acts.17.28\"></r>, <r v=\"Acts.17.29\"></r>, <r v=\"Rev.22.16\"></r>.</s> <s n=\"3.\"><b>race</b>, <b>nation</b>; <r v=\"Mark.7.28\"></r>, <r v=\"Acts.4.36\"></r> <r v=\"Acts.7.19\"></r> <r v=\"Acts.18.2\"></r>, <r v=\"Acts.18.24\"></r>, <r v=\"2Cor.11.26\"></r>, <r v=\"Phil.3.5\"></r>, <r v=\"Gal.1.14\"></r>, <r v=\"1Pet.2.9\"></r>.</s> <s n=\"4.\"><b>kind</b>, <b>sort</b>, <b>class</b>: <r v=\"Matt.13.47\"></r> <r v=\"Matt.17.21\"></r>, Rec., <r v=\"Mark.9.29\"></r>, <r v=\"1Cor.12.10\"></r>, <r v=\"1Cor.12.28\"></r> <r v=\"1Cor.14.10\"></r>.†</s>"},"G1052":{"l":"Γαλάτης","o":1,"ar":"<f><o>Γαλάτης</o>، <g>-ου, ὁ</g> (وكان أصلاً مرادفًا لـ <g>Κέλτης</g> في اليونانية الكلاسيكية، أي الكلتيّ؛ قارن <r v=\"1Macc.8.2\"></r>، وانظر المدخل التالي)، </f> <s><b>غلاطيّ</b>: <r v=\"Gal.3.1\"></r>.†</s>","en":"<f><o>Γαλάτης</o>, <g>-ου, ὁ</g> (originally syn. with cl. <g>Κέλτης</g>; cf. <r v=\"1Macc.8.2\"></r>, and v. next word), </f> <s><b>a Galatian</b>: <r v=\"Gal.3.1\"></r>.†</s>"},"G1064":{"l":"γαστήρ","o":9,"ar":"<f><o>γαστήρ</o>، <g>-τρός, ἡ</g>، </f> <s> <s n=\"1.\"><b>البطن</b>: مجازيًا، <b>شَرِه، نَهِم</b>، <r v=\"Titus.1.12\"></r>. </s> <s n=\"2.\"><b>الرحم</b>: <g>ἐν γ. ἔχειν</g>، <b>تكون حبلى</b>، <r v=\"Matt.1.18\"></r>، <r v=\"Matt.1.23\"></r> <i>(السبعينية)</i> <r v=\"Matt.24.19\"></r>، <r v=\"Mark.13.17\"></r>، <r v=\"Luke.21.23\"></r>، <r v=\"1Thess.5.3\"></r>، <r v=\"Rev.12.2\"></r>؛ <g>εν γ. συλλαμβ.</g>، <i>تحبل</i>، <r v=\"Luke.1.31\"></r>.†</s></s>","en":"<f><o>γαστήρ</o>, <g>-τρός, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H990\">בֶּטֶן</h>, <g>ἐν γ. ἔχειν</g> for <h n=\"H2029\">הרה</h>, <g>ἐν γ. λαμβάνειν</g> for <h n=\"H2734\">חרה</h> ;]</e> </et> <s> <s n=\"1.\"><b>the belly</b>: metaph., <b>a glutton</b>, <r v=\"Titus.1.12\"></r>. </s> <s n=\"2.\"><b>the womb</b>: <g>ἐν γ. ἔχειν</g>, <b>to be with child</b>, <r v=\"Matt.1.18\"></r>, <r v=\"Matt.1.23\"></r> <i>(LXX)</i> <r v=\"Matt.24.19\"></r>, <r v=\"Mark.13.17\"></r>, <r v=\"Luke.21.23\"></r>, <r v=\"1Thess.5.3\"></r>, <r v=\"Rev.12.2\"></r>; <g>εν γ. συλλαμβ.</g>, <i>to conceive</i>, <r v=\"Luke.1.31\"></r>.†</s></s>"},"G1050":{"l":"Γάϊος","o":5,"ar":"<f><o>Γαῖος</o>، <g>-ου, ὁ</g>، </f> <s><b>غايس</b>، اسم رجل مسيحي؛ <s n=\"1.\">من مكدونية: <r v=\"Acts.19.29\"></r>. </s> <s n=\"2.\">من دربة: <r v=\"Acts.20.4\"></r>. </s> <s n=\"3.\">من كورنثوس: <r v=\"Rom.16.23\"></r>، <r v=\"1Cor.1.14\"></r>. </s> <s n=\"4.\">الذي وُجّهت إليه رسالة يوحنا الثالثة: <r v=\"3John.1.1\"></r>.†</s> </s>","en":"<f><o>Γαῖος</o>, <g>-ου, ὁ</g> (<g>Γάϊος</g>, Rec.), </f> <s><b>Gaius</b>, the name of a Christian; <s n=\"1.\">of Macedonia: <r v=\"Acts.19.29\"></r>. </s> <s n=\"2.\">Of Derbe: <r v=\"Acts.20.4\"></r>. </s> <s n=\"3.\">Of Corinth: <r v=\"Rom.16.23\"></r>, <r v=\"1Cor.1.14\"></r>. </s> <s n=\"4.\">The one to whom III Ep. Jo is addressed: <r v=\"3John.1.1\"></r>.†</s> </s>"},"G1017":{"l":"βραβεῖον","o":2,"ar":"<f>* <o>βραβεῖον</o>، <g>-ου, τό</g> </f> <s><b>جعالة، جائزة</b> في المباريات: <r v=\"1Cor.9.24\"></r>؛ مجازيًا، عن مكافأة المسيحي، <r v=\"Phil.3.14\"></r>.†</s>","en":"<f>* <o>βραβεῖον</o>, <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>βραβεύς</g>, <i>an umpire</i>), </e> </et> <s><b>a prize</b> in the games: <r v=\"1Cor.9.24\"></r>; metaph., of the Christian's reward, <r v=\"Phil.3.14\"></r>.†</s>"},"G1018":{"l":"βραβεύω","o":1,"ar":"<f>** <o>βραβεύω</o> </f> <s> <s n=\"(a)\">أصلاً: <b>كان حَكَمًا</b> (في المباريات)؛ ومن ثمّ، </s> <s n=\"(b)\">عمومًا: <b>حكم بين، فصل</b>: <r v=\"Col.3.15\"></r>؛ </s> <s n=\"(c)\">عند الكتّاب المتأخرين: <b>دبّر، ساد، تحكّم</b> (قارن <g>κατα-βραβεύω</g>).†</s> </s>","en":"<f>** <o>βραβεύω</o> </f> <et> <e t=\"derivation\">(&lt; <g>βραβεύς</g>, <i>an umpire</i>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.10.12\"></r> * ;]</e> </et> <s> <s n=\"(a)\">prop., <b>to act as umpire</b>; hence, </s> <s n=\"(b)\">generally, <b>to arbitrate, decide</b> (Isocr., Dem.; Lft., <i>Col.</i>, l.c.; MM, s.v.): <r v=\"Col.3.15\"></r>; </s> <s n=\"(c)\">in some late writers, <b>to direct, rule, control</b> (so in Col., l.c., acc. to Thayer, s.v., Meyer, in l.), (cf. <g>κατα-βραβεύω</g>).†</s> </s>"},"G1029":{"l":"βρόχος","o":1,"ar":"<f><o>βρόχος</o>، <g>-ου, ὁ</g>، </f> <s><b>أُنشوطة، عقدة منزلقة، رَسَن</b>: مجازيًا: <b>قيد</b> (لا <i>شَرَكًا</i> كما في الترجمة المعتمدة): <r v=\"1Cor.7.35\"></r>.†</s>","en":"<f><o>βρόχος</o>, <g>-ου, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.6.5\"></r> (<h n=\"H3027\">יָד</h>) <r v=\"Prov.7.21\"></r> (<h n=\"H2506\">חֵלֶק</h>) <r v=\"Prov.22.25\"></r> (<h n=\"H4170\">מֹוקֵשׁ</h>), <r v=\"3Macc.4.8\"></r> * ;]</e> </et> <s><b>a noose, a slip-knot, a halter</b>: metaph., <b>a restraint</b> (not, as AV, R, txt., <i>a snare</i>): <r v=\"1Cor.7.35\"></r>.†</s>"},"G1073":{"l":"γέμω","o":11,"ar":"<f><o>γέμω</o> (لا يُستعمل إلا في المضارع والماضي الناقص)، </f> <s><b>كان مملوءًا، امتلأ</b>؛ <s n=\"1.\">في اليونانية الكلاسيكية: أصلاً عن السفينة (المشحونة). </s> <s n=\"2.\">عمومًا، <s n=\"(a)\">مع المضاف إليه للشيء: <r v=\"Matt.23.27\"></r>، <r v=\"Luke.11.39\"></r>، <r v=\"Rom.3.14\"></r> <i>(السبعينية)</i>، <r v=\"Rev.4.6\"></r>، <r v=\"Rev.4.8\"></r> <r v=\"Rev.5.8\"></r> <r v=\"Rev.15.7\"></r> <r v=\"Rev.17.3\"></r> <r v=\"Rev.7.4\"></r> <r v=\"Rev.21.9\"></r> </s> <s n=\"(b)\">يليه <g>ἐκ</g>: <r v=\"Matt.23.25\"></r>؛ </s> <s n=\"(c)\">مع المنصوب للشيء، كما في اليونانية المتأخرة: <r v=\"Rev.17.3\"></r>.</s> †</s> </s>","en":"<f><o>γέμω</o> (used only in pres. and impf.), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4390\">מלא</h>, <h n=\"H5375\">נשׂא</h> ;]</e> </et> <s><b>to be full</b>; <s n=\"1.\">properly, of a ship (Xen.). </s> <s n=\"2.\">Generally (Plat., al.), <s n=\"(a)\">c. gen. rei: <r v=\"Matt.23.27\"></r>, <r v=\"Luke.11.39\"></r>, <r v=\"Rom.3.14\"></r> <i>(LXX)</i>, <r v=\"Rev.4.6\"></r>, <r v=\"Rev.4.8\"></r> <r v=\"Rev.5.8\"></r> <r v=\"Rev.15.7\"></r> <r v=\"Rev.17.3\"></r> (Rec.) <r v=\"Rev.7.4\"></r> <r v=\"Rev.21.9\"></r> </s> <s n=\"(b)\">seq. <g>ἐκ</g>: <r v=\"Matt.23.25\"></r>; </s> <s n=\"(c)\">c. acc. rei (called a solecism in WM, 251; Bl., §36, 4), as in later Gk. from Byz. to Mod. times (Jannaris, <i>Gr.</i>, 1319): <r v=\"Rev.17.3\"></r>.</s> †</s> </s>"},"G1091":{"l":"γεώργιον","o":1,"ar":"<f><o>γεώργιον</o>، <g>-ου, τό</g> </f> <s> <s n=\"1.\"><b>حقل</b> (<r v=\"Prov.24.5\"></r>، <r v=\"Prov.24.30\"></r>). </s> <s n=\"2.\"><b>فلاحة، زراعة، حراثة</b> (<r v=\"Prov.6.7\"></r> <r v=\"Prov.9.12\"></r>، <r v=\"Jer.28.23\"></r>، <r v=\"Sir.27.6\"></r>): <r v=\"1Cor.3.9\"></r>.†</s></s>","en":"<f><o>γεώργιον</o>, <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>γεωργός</g>), </e> <e t=\"septuagint\">[in LXX, freq. in Pr., for <h n=\"H7704\">שָׂדֶה</h>, etc. ;]</e> </et> <s> <s n=\"1.\"><b>a field</b> (<r v=\"Prov.24.5\"></r>, <r v=\"Prov.24.30\"></r>, Strabo). </s> <s n=\"2.\"><b>cultivation, husbandry, tillage</b> (<r v=\"Prov.6.7\"></r> <r v=\"Prov.9.12\"></r>, <r v=\"Jer.28.23\"></r>, <r v=\"Sir.27.6\"></r>): <r v=\"1Cor.3.9\"></r>.†</s></s>"},"G1016":{"l":"βοῦς","o":8,"ar":"<f><o>βοῦς</o>، <g>βοός, ὁ, ἡ</g>، </f> <s><b>ثور، بقرة</b>: <r v=\"Luke.13.15\"></r> <r v=\"Luke.14.5\"></r>، <r v=\"Luke.14.19\"></r> <r v=\"John.2.14\"></r>، <r v=\"John.2.15\"></r> <r v=\"1Cor.9.9\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.5.18\"></r>.†</s>","en":"<f><o>βοῦς</o>, <g>βοός, ὁ, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1241\">בָּקָר</h>;]</e> </et> <s><b>an ox, a cow</b>: <r v=\"Luke.13.15\"></r> <r v=\"Luke.14.5\"></r>, <r v=\"Luke.14.19\"></r> <r v=\"John.2.14\"></r>, <r v=\"John.2.15\"></r> <r v=\"1Cor.9.9\"></r> <i>(LXX)</i>, <r v=\"1Tim.5.18\"></r>.†</s>"},"G1051":{"l":"γάλα","o":5,"ar":"<f><o>γάλα</o>، <g>-ακτος, τό</g> </f> <s><b>لبن</b>: <r v=\"1Cor.9.7\"></r>. ومجازيًا، عن مبادئ التعليم المسيحي: <r v=\"1Cor.3.2\"></r>، <r v=\"Heb.5.12\"></r>، <r v=\"Heb.5.13\"></r>؛ <g>τὸ λογικὸν ἄδολον γ.</g>، <b>اللبن العقلي (الروحي) العديم الغش</b>، <r v=\"1Pet.2.2\"></r> (وفي الترجمة المعتمدة: <i>لبن الكلمة</i>).†</s>","en":"<f><o>γάλα</o>, <g>-ακτος, τό</g> </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2461\">חלב</h> ;]</e> </et> <s><b>milk</b>: <r v=\"1Cor.9.7\"></r>. Metaph., of elementary Christian teaching: <r v=\"1Cor.3.2\"></r>, <r v=\"Heb.5.12\"></r>, <r v=\"Heb.5.13\"></r>; <g>τὸ λογικὸν ἄδολον γ.</g>, <b>the rational (spiritual) genuine milk</b> (v. Hort, in l.), <r v=\"1Pet.2.2\"></r> (in support of AV, <i>milk of the word</i>, v. <i>ICC</i>, in l.).†</s>"},"G1044":{"l":"γάγγραινα","o":1,"ar":"<f>*† <o>γάγγραινα</o>، <g>-ης, ἡ</g>، </f> <s><b>غنغرينا، آكلة</b>، تؤدي إلى موت الأنسجة: <r v=\"2Tim.2.17\"></r>.†</s>","en":"<f>*† <o>γάγγραινα</o>, <g>-ης, ἡ</g>, </f> <s><b>a gangrene, an eating sore</b>, which leads to mortification: <r v=\"2Tim.2.17\"></r>.†</s>"},"G1081":{"l":"γέννημα","o":4,"ar":"<f><o>γέννημα</o>، <g>-τος, τό</g> </f> <s><b>نسل، ذرّية</b> البشر أو الحيوانات: <g>ἐχιδνῶν</g>، <r v=\"Matt.3.7\"></r> <r v=\"Matt.12.34\"></r> <r v=\"Matt.23.33\"></r>، <r v=\"Luke.3.7\"></r> (وقارن <g>γένημα</g>).†</s>","en":"<f><o>γέννημα</o>, <g>-τος, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>γεννάω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8393\">תְּבוּאָה</h> ;]</e> </et> <s><b>offspring</b> of men or animals: <g>ἐχιδνῶν</g>, <r v=\"Matt.3.7\"></r> <r v=\"Matt.12.34\"></r> <r v=\"Matt.23.33\"></r>, <r v=\"Luke.3.7\"></r> (and elsewhere in Rec. for <g>γένημα</g>, q.v.).†</s>"},"G1036":{"l":"βυθίζω","o":2,"ar":"<f>** <o>βυθίζω</o> </f> <s>متعدٍّ: <b>يُغرق، يُغرّق</b>: مجازيًا، <g>εἰς ὄλεθρον</g>، <r v=\"1Tim.6.9\"></r>؛ المبني للمجهول: <i>يغرق</i>، لازمًا: <r v=\"Luke.5.7\"></r>.†</s>","en":"<f>** <o>βυθίζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>βυθός</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.12.4\"></r> * ;]</e> </et> <s>trans., <b>to cause to sink, to sink</b>: metaph., <g>εἰς ὄλεθρον</g>, <r v=\"1Tim.6.9\"></r>; pass., <i>to sink</i>, intrans.: <r v=\"Luke.5.7\"></r>.†</s>"},"G1037":{"l":"βυθός","o":1,"ar":"<f><o>βυθός</o>، <g>-οῦ, ὁ</g>، </f> <s> <s n=\"1.\"><b>القاع</b>. </s> <s n=\"2.\"><b>عمق</b> البحر، <b>اللُّجّة، العُمق</b>: <r v=\"2Cor.11.25\"></r>.†</s> </s>","en":"<f><o>βυθός</o>, <g>-οῦ, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.15.5\"></r>, <r v=\"Neh.9.11\"></r> (<h n=\"H4688\">מְצוֹלָה</h>), <r v=\"LXX:Ps.67.22\"></r> <r v=\"LXX:Ps.68.2\"></r>, <r v=\"LXX:Ps.68.15\"></r> <r v=\"LXX:Ps.106.24\"></r> (<h n=\"H4688\">מְצוּלָה</h>)* ;]</e> </et> <s> <s n=\"1.\"><b>the bottom</b>. </s> <s n=\"2.\"><b>the depth</b> of the sea, <b>the deep sea</b>: <r v=\"2Cor.11.25\"></r>.†</s> </s>"},"G1013":{"l":"βούλημα","o":3,"ar":"<f><o>βούλημα</o>، <g>-τος, τό</g> </f> <s><b>قصد، مشيئة</b>: <r v=\"Acts.27.43\"></r>، <r v=\"Rom.9.19\"></r>، <r v=\"1Pet.4.3\"></r>.†</s>","en":"<f><o>βούλημα</o>, <g>-τος, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>βούλομαι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.9.10\"></r> (<h n=\"H1847\">דַּעַת</h>), <r v=\"2Macc.15.5\"></r>, <r v=\"4Macc.8.18\"></r>*;]</e> </et> <s><b>purpose, will</b>: <r v=\"Acts.27.43\"></r>, <r v=\"Rom.9.19\"></r>, <r v=\"1Pet.4.3\"></r>.†</s> <sy><i>SYN.</i>: <g>θέλημα</g>.</sy>"},"G1061":{"l":"γαμίσκω","o":2,"ar":"<f>* <o>γαμίσκω</o>، = <g>γαμίζω</g>، انظره: <r v=\"Luke.20.34\"></r>، <r v=\"Luke.20.35\"></r>.†</f>","en":"<f>* <o>γαμίσκω</o>, = <g>γαμίζω</g>, q.v.: <r v=\"Luke.20.34\"></r>, <r v=\"Luke.20.35\"></r> WH, mg. (Arist.).†</f>"},"G1011":{"l":"βουλεύω","o":6,"ar":"<f><o>βουλεύω</o> </f> <s><b>تشاور، تداول، عزم</b>. وفي الصيغة الوسطى، <s n=\"1.\"><b>تشاور مع نفسه، تأمّل، فكّر</b>: يليه <g>εἰ</g>، <r v=\"Luke.14.31\"></r>. </s> <s n=\"2.\"><b>قرّر في نفسه، عزم</b>: مع المصدر، <r v=\"Acts.5.33\"></r> <r v=\"Acts.27.39\"></r>؛ مع المنصوب، <r v=\"2Cor.1.17\"></r>؛ يليه <g>ἵνα</g>، <r v=\"John.11.53\"></r> <r v=\"John.12.10\"></r> (قارن <g>παρα-, συμ-</g>).†</s> </s>","en":"<f><o>βουλεύω</o> </f> <et> <e t=\"derivation\">(&lt; <g>βουλή</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3289\">יעץ</h>;]</e> </et> <s><b>to take counsel, deliberate, resolve</b>. In mid., <s n=\"1.\"><b>to take counsel with oneself, consider</b>: seq. <g>εἰ</g>, <r v=\"Luke.14.31\"></r>. </s> <s n=\"2.\"><b>to determine with oneself, resolve</b>: c. inf., <r v=\"Acts.5.33\"></r> <r v=\"Acts.27.39\"></r>; c. acc., <r v=\"2Cor.1.17\"></r>; seq. <g>ἵνα</g>, <r v=\"John.11.53\"></r> <r v=\"John.12.10\"></r> (cf. <g>παρα-, συμ-</g>).†</s> </s>"},"G1078":{"l":"γένεσις","o":5,"ar":"<f><o>γένεσις</o>، <g>-εως, ἡ</g> </f> <s> <s n=\"1.\"><b>أصل، نَسَب</b>: <g>βίβλος γενέσεως</g> (كما في <r v=\"Gen.2.4\"></r> <r v=\"Gen.5.1\"></r>)، <r v=\"Matt.1.1\"></r>. </s> <s n=\"2.\"><b>ولادة، ميلاد</b>: <r v=\"Matt.1.18\"></r>، <r v=\"Luke.1.14\"></r>؛ <g>πρόσωπον τῆς γ.</g>، <i>وجه ولادته</i> (أي «ما خلقه الله ليكونه»)، <r v=\"Jas.1.23\"></r>؛ <g>ὁ τροχὸς τῆς γ.</g>، <i>دائرة (مسار) الميلاد</i> أو <i>الخليقة</i> (أي «دائرة طبيعة الإنسان بحسب قصدها الإلهي الأصلي»)، <r v=\"Jas.3.6\"></r>.†</s></s>","en":"<f><o>γένεσις</o>, <g>-εως, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γίγνομαι</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8435\">תֹּולֵדֹת</h> ;]</e> </et> <s> <s n=\"1.\"><b>origin, lineage</b>: <g>βίβλος γενέσεως</g> (as in <r v=\"Gen.2.4\"></r>a <r v=\"Gen.5.1\"></r>), <r v=\"Matt.1.1\"></r>. </s> <s n=\"2.\"><b>birth</b>: <r v=\"Matt.1.18\"></r>, <r v=\"Luke.1.14\"></r> (Rec. <g>γέννησις</g>); <g>πρόσωπον τῆς γ.</g>, <i>face of his birth</i> (\"what God made him to be,\" Hort., in l.), <r v=\"Jas.1.23\"></r>; <g>ὁ τροχὸς τῆς γ.</g>, <i>the wheel (course) of birth</i> or <i>creation</i> (\"the wheel of man's nature according to its original Divine purpose,\" Hort), <r v=\"Jas.3.6\"></r>.†</s></s>"},"G1095":{"l":"γηράσκω","o":2,"ar":"<f><o>γηράσκω</o> (وأيضًا <x><g>γηράω</g></x>؛ مشتقة من <x><g>γῆρας</g></x>)،</f> <s><b>شاخ</b>: <r v=\"John.21.18\"></r>، <r v=\"Heb.8.13\"></r>.†</s>","en":"<f><o>γηράσκω</o> (also <x><g>γηράω</g></x>; &lt; <x><g>γῆρας</g></x>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2204\">זקן</h>;]</e> </et> <s><b>to grow old</b>: <r v=\"John.21.18\"></r>, <r v=\"Heb.8.13\"></r>.†</s> <sy><i>SYN.</i>: <x><g>παλαιοῦμαι</g></x>.</sy>"},"G1007":{"l":"Βοσόρ","o":1,"ar":"<f><o>Βοσόρ</o> انظر <g>Βεώρ</g>.</f>","en":"<f><o>Βοσόρ</o> v. <g>Βεώρ</g>.</f>"},"G1005":{"l":"βορρᾶς","o":2,"ar":"<f><o>βορρᾶς</o>، <g>-ᾶ</g> </f> <s> <s n=\"1.\"><b>بورياس، ريح الشمال</b>. </s> <s n=\"2.\"><b>الشمال</b>: <r v=\"Luke.13.29\"></r>، <r v=\"Rev.21.13\"></r>.†</s></s>","en":"<f><o>βορρᾶς</o>, <g>-ᾶ</g> (Attic contr. of <g>Βορέας</g>, the North wind personified), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6828\">צָפֹון</h>;]</e> </et> <s> <s n=\"1.\"><b>Boreas, the North wind</b>. </s> <s n=\"2.\"><b>the north</b>: <r v=\"Luke.13.29\"></r>, <r v=\"Rev.21.13\"></r>.†</s></s>"},"G1066":{"l":"Γεδεών","o":1,"ar":"<f><o>Γεδεών</o>، <g>ὁ</g>، لا يُصرَّف في السبعينية والعهد الجديد (بالعبرية <h n=\"H1439\">גִּדְעוֹן</h>)، </f> <s><b>جدعون</b> (<r v=\"Judg.6-Judg.8\"></r>): <r v=\"Heb.11.32\"></r>.†</s>","en":"<f><o>Γεδεών</o>, <g>ὁ</g>, indecl. in LXX and NT, in FlJ, <i>Ant.</i>, v. 6, 3 and 4 <g>-ῶνος</g> (Heb. <h n=\"H1439\">גִּדְעוֹן</h>), </f> <s><b>Gideon</b> (<r v=\"Judg.6-Judg.8\"></r>): <r v=\"Heb.11.32\"></r>.†</s>"},"G1039":{"l":"βύσσινος","o":5,"ar":"<f><o>βύσσινος</o>، <g>-η, -ον</g> </f> <s>مصنوع من <g>βύσσος</g>، <b>من البَزّ (الكتان الناعم)</b>: <r v=\"Rev.18.12\"></r>، <r v=\"Rev.18.16\"></r> <r v=\"Rev.19.8\"></r>، <r v=\"Rev.19.14\"></r>.†</s>","en":"<f><o>βύσσινος</o>, <g>-η, -ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>βύσσος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8336\">שֵׁשׁ</h>, <h n=\"H948\">בּוּץ</h>, etc. ;] </e> </et> <s>made of <g>βύσσος</g>, <b>fine linen</b>: <r v=\"Rev.18.12\"></r>, <r v=\"Rev.18.16\"></r> <r v=\"Rev.19.8\"></r>, <r v=\"Rev.19.14\"></r>.†</s>"},"G1009":{"l":"βότρυς","o":1,"ar":"<f><o>βότρυς</o>، <g>-οῦ, ὁ</g>، </f> <s><b>عنقود عنب</b>: <r v=\"Rev.14.18\"></r> (قارن <g>στραφυλή</g>) .†</s>","en":"<f><o>βότρυς</o>, <g>-οῦ, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H811\">אֶשְׁכֹּל</h>;]</e> </et> <s><b>a cluster of grapes</b>: <r v=\"Rev.14.18\"></r> (cf. <g>στραφυλή</g>) .†</s>"},"G1071":{"l":"γέλως","o":1,"ar":"<f><o>γέλως</o>، <g>-ωτος, ὁ</g>، </f> <s><b>ضحك</b>: <r v=\"Jas.4.9\"></r>.†</s>","en":"<f><o>γέλως</o>, <g>-ωτος, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7814\">שְׂחוֹק</h> ;]</e> </et> <s><b>laughter</b>: <r v=\"Jas.4.9\"></r>.†</s>"},"G1032":{"l":"βρύω","o":1,"ar":"<f>* <o>βρύω</o>، </f> <s><b>امتلأ حتى الفيض</b>؛ <s n=\"1.\">في اليونانية الكلاسيكية: عن الأرض المُنبتة للنبات. </s> <s n=\"2.\">في اليونانية الكلاسيكية: عن النباتات المُخرجة براعمها. </s> <s n=\"3.\">عن الينابيع، <b>فاض</b> بالماء: <r v=\"Jas.3.11\"></r>.†</s> </s>","en":"<f>* <o>βρύω</o>, poët., late prose and vernac., </f> <s><b>to be full to bursting</b>; <s n=\"1.\">of the earth producing vegetation. </s> <s n=\"2.\">Of plants putting forth buds. </s> <s n=\"3.\">Of springs, <b>to gush with</b> water: <r v=\"Jas.3.11\"></r>.†</s> </s>"},"G1008":{"l":"βοτάνη","o":1,"ar":"<f><o>βοτάνη</o>، <g>-ῆς, ἡ</g> </f> <s> <s n=\"1.\"><b>عشب، علف</b>. </s> <s n=\"2.\"><b>نبات أخضر</b>: <r v=\"Heb.6.7\"></r>.†</s> </s>","en":"<f><o>βοτάνη</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βόσκω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H6212\">עֵשֶׂב</h>,<h n=\"H1877\">דֶשֶׁא</h>,<h n=\"H2682\">חָצִיר</h>;]</e> </et> <s> <s n=\"1.\"><b>grass, fodder</b>. </s> <s n=\"2.\"><b>green herb</b>: <r v=\"Heb.6.7\"></r>.†</s> </s> <sy><i>SYN.</i>: <g>λάχανον</g>, <i>a garden herb</i>, a vegetable.</sy>"},"G1004":{"l":"βόρβορος","o":1,"ar":"<f><o>βόρβορος</o>، <g>-ου, ὁ</g>، </f> <s><b>حمأة، وحل</b>: <r v=\"2Pet.2.22\"></r>.†</s>","en":"<f><o>βόρβορος</o>, <g>-ου, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"LXX:Jer.45.6\"></r> (<h n=\"H2916\">טִיט</h>)* ;]</e> </et> <s><b>mud, filth</b>: <r v=\"2Pet.2.22\"></r>.†</s>"},"G1024":{"l":"βραχύς","o":5,"ar":"<f><o>βραχύς</o>، <g>-εῖα, -ύ</g>، </f> <s><b>قصير</b>؛ <s n=\"(a)\">عن الزمن: <b>قصير، قليل</b>: <g>βραχύ</g>، <r v=\"Acts.5.34\"></r>؛ <g>μετὰ β.</g>، <r v=\"Luke.22.58\"></r>؛ <g>β. τι</g>، <b>زمانًا قليلاً</b>، <r v=\"Heb.2.7\"></r>، <r v=\"Heb.2.9\"></r> (في هامش الترجمة المنقحة)؛ </s> <s n=\"(b)\">عن المسافة: <r v=\"Acts.27.28\"></r>؛ </s> <s n=\"(c)\">عن الكمية أو القيمة، <b>قليل، يسير</b>: <r v=\"John.6.7\"></r>، <r v=\"Heb.2.7\"></r>، <r v=\"Heb.2.9\"></r> (في متن الترجمة المنقحة)؛ في الجمع، <g>διὰ βραχέων</g>، <i>بكلمات قليلة</i>، <r v=\"Heb.13.22\"></r>.†</s></s>","en":"<f><o>βραχύς</o>, <g>-εῖα, -ύ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4592\">מְעַט</h> ;]</e> </et> <s><b>short</b>; <s n=\"(a)\">of time; <b>short, little</b>: <g>βραχύ</g>, <r v=\"Acts.5.34\"></r>; <g>μετὰ β.</g>, <r v=\"Luke.22.58\"></r>; <g>β. τι</g>, <b>a short time</b>, <r v=\"Heb.2.7\"></r>, <r v=\"Heb.2.9\"></r> RV, mg.; </s> <s n=\"(b)\">of distance: <r v=\"Acts.27.28\"></r>; </s> <s n=\"(c)\">of quantity or value, <b>little, few</b>: <r v=\"John.6.7\"></r>, <r v=\"Heb.2.7\"></r>, <r v=\"Heb.2.9\"></r> RV, txt.; pl., <g>διὰ βραχέων</g>, <i>in few words</i>, <r v=\"Heb.13.22\"></r>.†</s></s>"},"G1062":{"l":"γάμος","o":19,"ar":"<f><o>γάμος</o>، <g>-ου, ὁ</g>، </f> <s> <s n=\"1.\"><b>عُرس</b>، وخاصةً <b>وليمة العُرس</b>: <r v=\"Matt.22.8\"></r>، <r v=\"Matt.22.10\"></r>، <r v=\"Matt.22.11\"></r>، <r v=\"Matt.22.12\"></r>، <r v=\"John.2.1-John.2.3\"></r>، <r v=\"Rev.19.7\"></r>، <r v=\"Rev.19.9\"></r>؛ وفي الجمع، <r v=\"Matt.22.2-Matt.22.4\"></r>، <r v=\"Matt.22.9\"></r> <r v=\"Matt.25.10\"></r>، <r v=\"Luke.12.36\"></r> <r v=\"Luke.14.8\"></r>. </s> <s n=\"2.\"><b>زواج</b>: <r v=\"Heb.13.4\"></r>.†</s> </s>","en":"<f><o>γάμος</o>, <g>-ου, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4960\">מִשְׁתֶּה</h> ;]</e> </et> <s> <s n=\"1.\"><b>a wedding</b>, esp. <b>a wedding-feast</b>: <r v=\"Matt.22.8\"></r>, <r v=\"Matt.22.10\"></r>, <r v=\"Matt.22.11\"></r>, <r v=\"Matt.22.12\"></r>, <r v=\"John.2.1-John.2.3\"></r>, <r v=\"Rev.19.7\"></r>, <r v=\"Rev.19.9\"></r>; pl. (Field, <i>Notes</i>, 16), <r v=\"Matt.22.2-Matt.22.4\"></r>, <r v=\"Matt.22.9\"></r> <r v=\"Matt.25.10\"></r>, <r v=\"Luke.12.36\"></r> <r v=\"Luke.14.8\"></r>. </s> <s n=\"2.\"><b>marriage</b>: <r v=\"Heb.13.4\"></r> (Cremer, 666).†</s> </s>"},"G1027":{"l":"βροντή","o":12,"ar":"<f><o>βροντή</o>، <g>-ῆς, ἡ</g>، </f> <s><b>رعد</b>: <r v=\"Mark.3.17\"></r>، <r v=\"John.12.29\"></r>، <r v=\"Rev.4.5\"></r> <r v=\"Rev.6.1\"></r> <r v=\"Rev.8.5\"></r> <r v=\"Rev.10.3\"></r>، <r v=\"Rev.10.4\"></r> <r v=\"Rev.11.19\"></r> <r v=\"Rev.14.2\"></r> <r v=\"Rev.16.18\"></r> <r v=\"Rev.19.6\"></r>.†</s>","en":"<f><o>βροντή</o>, <g>-ῆς, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7482\">רַעַם</h> ;]</e> </et> <s><b>thunder</b>: <r v=\"Mark.3.17\"></r>, <r v=\"John.12.29\"></r>, <r v=\"Rev.4.5\"></r> <r v=\"Rev.6.1\"></r> <r v=\"Rev.8.5\"></r> <r v=\"Rev.10.3\"></r>, <r v=\"Rev.10.4\"></r> <r v=\"Rev.11.19\"></r> <r v=\"Rev.14.2\"></r> <r v=\"Rev.16.18\"></r> <r v=\"Rev.19.6\"></r>.†</s>"},"G1045":{"l":"Γάδ","o":1,"ar":"<f><o>Γάδ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H1410\">גָּד</h>)، </f> <s>جاد (<r v=\"Gen.30.11\"></r> <r v=\"Gen.49.13\"></r>، وفي مواضع أخرى): <r v=\"Rev.7.5\"></r>.†</s>","en":"<f><o>Γάδ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H1410\">גָּד</h>), </f> <s>Gad (<r v=\"Gen.30.11\"></r> <r v=\"Gen.49.13\"></r>, al.): <r v=\"Rev.7.5\"></r>.†</s>"},"G1072":{"l":"γεμίζω","o":8,"ar":"<f><o>γεμίζω</o> </f> <s><b>ملأ</b>؛ <s n=\"1.\">أصلاً، عن السفينة: <r v=\"Mark.4.37\"></r> (المبني للمجهول). </s> <s n=\"2.\">وعند الكتّاب المتأخرين، عمومًا، مع المنصوب، يليه المضاف إليه، <r v=\"Mark.15.36\"></r>، <r v=\"John.2.7\"></r>، <r v=\"John.6.13\"></r>، <r v=\"Rev.15.8\"></r>؛ <g>ἀπό</g>، <r v=\"Luke.15.16\"></r>؛ <g>ἐκ</g>، <r v=\"Luke.15.16\"></r>، <r v=\"Rev.8.5\"></r>. المبني للمجهول، مطلقًا: <r v=\"Luke.14.23\"></r>.†</s> </s>","en":"<f><o>γεμίζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>γέμω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.45.17\"></r> (<h n=\"H2943\">טען</h>), <r v=\"3Macc.5.47\"></r>, <r v=\"4Macc.3.14\"></r> * ;]</e> </et> <s><b>to fill</b>; <s n=\"1.\">properly, of a ship (Thuc, al.): <r v=\"Mark.4.37\"></r> (pass.). </s> <s n=\"2.\">In late writers, generally (MGr., v. Kennedy, <i>Sources</i>, 155), c. acc., seq. gen., <r v=\"Mark.15.36\"></r>, <r v=\"John.2.7\"></r> <r v=\"John.6.13\"></r>, <r v=\"Rev.15.8\"></r>; <g>ἀπό</g>, <r v=\"Luke.15.16\"></r>, Rec. WH, mg.; <g>ἐκ</g>, <r v=\"Luke.15.16\"></r>, WH, <r v=\"Rev.8.5\"></r>. Pass., absol.: <r v=\"Luke.14.23\"></r>.†</s> </s>"},"G1026":{"l":"βρέχω","o":8,"ar":"<f><o>βρέχω</o>، </f> <s> <s n=\"1.\"><b>بلّل</b>: <r v=\"Luke.7.38\"></r>، <r v=\"Luke.7.44\"></r>. </s> <s n=\"2.\">في اليونانية المتأخرة واللغة الدارجة = <g>ὕειν</g>، <b>أمطر، أنزل المطر</b>: <r v=\"Matt.5.45\"></r>؛ مجازيًا، <g>β. πῦρ κ. θεῖον</g>، <r v=\"Luke.17.29\"></r>؛ غير شخصي، <g>βρέχει</g>، <i>تمطر</i>: <r v=\"Jas.5.17\"></r>؛ ومع <g>ὐετός</g> فاعلاً، <r v=\"Rev.11.6\"></r>.†</s> </s>","en":"<f><o>βρέχω</o>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4305\">מטר</h>;]</e> </et> <s> <s n=\"1.\"><b>to wet</b>: <r v=\"Luke.7.38\"></r>, <r v=\"Luke.7.44\"></r>. </s> <s n=\"2.\">In late Gk. writers and vernac. = <g>ὕειν</g>, <b>to send rain, to rain</b> (Kennedy, <i>Sources</i>, 39, 155): <r v=\"Matt.5.45\"></r>; trop., <g>β. πῦρ κ. θεῖον</g>, <r v=\"Luke.17.29\"></r>; impers., <g>βρέχει</g>, <i>it rains</i>: <r v=\"Jas.5.17\"></r>; with <g>ὐετός</g> as subj., <r v=\"Rev.11.6\"></r>.†</s> </s>"},"G1090":{"l":"γεωργέω","o":1,"ar":"<f><o>γεωργέω</o>، <g>-ῶ</g></f> <s><b>فلح</b> الأرض: المبني للمجهول، <r v=\"Heb.6.7\"></r>.</s>","en":"<f><o>γεωργέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>γεωργός</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.27.26\"></r> (<h n=\"H4399\">מְלֶאכֶת</h> <h n=\"H7704\">הַשָּׂדֶה</h> <h n=\"H6213\">עָשָׂה</h>), <r v=\"1Esd.4.6\"></r>, <r v=\"1Macc.14.8\"></r>*;]</e> </et> <s><b>to till</b> the ground: pass., <r v=\"Heb.6.7\"></r>.</s>"},"G1067":{"l":"γέεννα","o":12,"ar":"<f>† <o>γέεννα</o> (<g>γέενα</g>، <r v=\"Mark.9.45\"></r>)، <g>-ης, ἡ</g> (ربما عن الآرامية <h n=\"H???\">גֵּיהִנָּם</h>، من العبرية <h n=\"H2011\">גֵּי הִנֹּם</h>، <r v=\"Neh.11.30\"></r>؛ <h n=\"H1121,H2011\">גֵּי בֶּן־הִנֹּם</h>، <r v=\"John.18.16\"></r>؛ <h n=\"H1121,H2011\">גֵּי בּנֵי־הִנֹּם</h>، <r v=\"2Kgs.23.10\"></r>؛ <i>وادي (ابن، بني) النَّوح</i>)؛ </f> <s><b>جهنم</b>، وادٍ غربي أورشليم وجنوبيها، كان موضعًا لعبادة النار منذ أيام آحاز، فنجّسه يوشيا وصار مطرحًا لنفايات المدينة. ثم صار الاسم فيما بعد رمزًا لمكان العقاب الآتي، كما في العهد الجديد: <r v=\"Matt.5.29\"></r>، <r v=\"Matt.5.30\"></r> <r v=\"Matt.10.28\"></r>، <r v=\"Mark.9.43\"></r>، <r v=\"Mark.9.45\"></r>، <r v=\"Mark.9.47\"></r>، <r v=\"Luke.12.5\"></r>، <r v=\"Jas.3.6\"></r>؛ <g>γ. τ. πυρός</g>، <r v=\"Matt.5.22\"></r> <r v=\"Matt.18.19\"></r>، والأرجح إشارةً إلى نيران مولك؛ <g>υἱὸς γεέννης</g>، <r v=\"Matt.23.15\"></r>؛ <g>κρίσις γεέννης</g>، <r v=\"Matt.23.33\"></r>.†</s>","en":"<f>† <o>γέεννα</o> (<g>γέενα</g>, <r v=\"Mark.9.45\"></r>, Rec.), <g>-ης, ἡ</g> (perh. through Aram. <h n=\"H???\">גֵּיהִנָּם</h>, from Heb. <h n=\"H2011\">גֵּי הִנֹּם</h>, <r v=\"Neh.11.30\"></r>; <h n=\"H1121,H2011\">גֵּי בֶּן־הִנֹּם</h>, <r v=\"John.18.16\"></r>; <h n=\"H1121,H2011\">גֵּי בּנֵי־הִנֹּם</h>, <r v=\"2Kgs.23.10\"></r>; <i>valley of (the son, sons of) lamentation</i>); </f> <et> <e t=\"septuagint\">[in LXX the nearest approach to <g>γ.</g> is <g>γαίεννα</g>, <r v=\"Josh.18.16\"></r> (<g>Γαὶ Ὀννόμ</g>, A), elsewhere <g>φάραγξ Ὀνόμ</g> (<r v=\"Josh.15.8\"></r>, al.), V. Swete on <r v=\"Mark.9.43\"></r> ;]</e> </et> <s><b>Gehenna</b>, a valley W. and S. of Jerusalem, which as the site of fire-worship from the time of Ahaz, was desecrated by Josiah and became a dumping-place for the offal of the city. Later, the name was used as a symbol of the place of future punishment, as in NT: <r v=\"Matt.5.29\"></r>, <r v=\"Matt.5.30\"></r> <r v=\"Matt.10.28\"></r>, <r v=\"Mark.9.43\"></r>, <r v=\"Mark.9.45\"></r>, <r v=\"Mark.9.47\"></r>, <r v=\"Luke.12.5\"></r>, <r v=\"Jas.3.6\"></r>; <g>γ. τ. πυρός</g>, <r v=\"Matt.5.22\"></r> <r v=\"Matt.18.19\"></r>, prob. with ref. to fires of Moloch (<i>DB</i>, ii, 119b); <g>υἱὸς γεέννης</g>, <r v=\"Matt.23.15\"></r>; <g>κρίσις γεέννης</g>, <r v=\"Matt.23.33\"></r>.†</s>"},"G1021":{"l":"βραδύς","o":3,"ar":"<f>* <o>βραδύς</o>، <g>-εῖα, -ύ</g>، </f> <s><b>بطيء</b>: <g>εἰς τὸ λαλῆσαι</g>، <r v=\"Jas.1.19\"></r>؛ مجازيًا عن الفهم: <g>β. τ. καρδίᾳ</g>، مقرونًا بـ <g>ἀνόητος</g>، <r v=\"Luke.24.25\"></r>.†</s>","en":"<f>* <o>βραδύς</o>, <g>-εῖα, -ύ</g>, </f> <s><b>slow</b>: <g>εἰς τὸ λαλῆσαι</g>, <r v=\"Jas.1.19\"></r>; metaph., of the understanding: <g>β. τ. καρδίᾳ</g>, assoc. with <g>ἀνόητος</g>, <r v=\"Luke.24.25\"></r>.†</s>"},"G1099":{"l":"γλυκύς","o":4,"ar":"<f><o>γλυκύς</o>، <g>-εῖα, -ύ</g>، </f> <s><b>حلو، عذب</b>: <r v=\"Jas.3.11\"></r>، <r v=\"Jas.3.12\"></r>؛ عكس <g>πικρόν, ἁλυκόν</g>، <r v=\"Rev.10.9\"></r>، <r v=\"Rev.10.10\"></r>.†</s>","en":"<f><o>γλυκύς</o>, <g>-εῖα, -ύ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4966\">מָתֹוק</h> ;] </e> </et> <s><r v=\"Jas.3.11\"></r>, <r v=\"Jas.3.12\"></r>; opp. to <g>πικρόν, ἁλυκόν</g>, <r v=\"Rev.10.9\"></r>, <r v=\"Rev.10.10\"></r>.†</s>"},"G1075":{"l":"γενεαλογέομαι","o":1,"ar":"<f><o>γενεαλογέω</o>، <g>-ῶ</g> </f> <s><b>يتتبّع النسب، يُحسَب في سلسلة النسب</b>؛ المبني للمجهول، يليه <g>ἐκ</g>: <r v=\"Heb.7.6\"></r>.†</s>","en":"<f><o>γενεαλογέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γενεά, λέγω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.5.1\"></r> (<h n=\"H3187\">יחשׁ</h>)* ;]</e> </et> <s><b>to trace ancestry, reckon genealogy</b>; pass., seq. <g>ἐκ</g>: <r v=\"Heb.7.6\"></r>.†</s>"},"G1054":{"l":"Γαλατικός","o":2,"ar":"<f><o>Γαλατικός</o>، <g>-ή, -όν</g>، </f> <s><b>غلاطي</b>، منسوب إلى غلاطية: <r v=\"Acts.16.6\"></r>، <r v=\"Acts.18.23\"></r>.†</s>","en":"<f><o>Γαλατικός</o>, <g>-ή, -όν</g> (v. previous word), </f> <s><b>Galatian</b>, belonging to Galatia: <r v=\"Acts.16.6\"></r> <r v=\"Acts.18.23\"></r>.†</s>"},"G1048":{"l":"Γάζα","o":1,"ar":"<f><o>Γάζα -ης</o>، <g>ἡ</g> (العبرية <h n=\"H5804\">עַזָּה</h>)، </f> <s><b>غزة</b>، وهي في العهد القديم إحدى مدن الفلسطينيين الخمس الرئيسية: <r v=\"Acts.8.26\"></r>.†</s>","en":"<f><o>Γάζα -ης</o>, <g>ἡ</g> (Heb. <h n=\"H5804\">עַזָּה</h>), </f> <s><b>Gaza</b>, in OT, one of the five chief cities of the Philistines: <r v=\"Acts.8.26\"></r>.†</s>"},"G1020":{"l":"βραδυπλοέω","o":1,"ar":"<f>*† <o>βραδυπλοέω</o>، <g>-ῶ</g> </f> <s><b>سافر في البحر ببطء</b>: <r v=\"Acts.27.7\"></r>.†</s>","en":"<f>*† <o>βραδυπλοέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βραδύς, πλοῦς</g>), </e> </et> <s><b>to sail slowly</b>: <r v=\"Acts.27.7\"></r>.†</s>"},"G1040":{"l":"βύσσος","o":1,"ar":"<f><o>βύσσος</o>، <g>-οῦ, ἡ</g> (قارن العبرية <h n=\"H948\">בּוּץ</h>)، </f> <s><b>بَزّ</b>، نوع من الكتان الناعم، وأيضًا <b>الكتان</b> المصنوع منه: <r v=\"Luke.16.19\"></r>.†</s>","en":"<f><o>βύσσος</o>, <g>-οῦ, ἡ</g> (cf. Heb. <h n=\"H948\">בּוּץ</h>), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8336\">שֵׁשׁ</h>, <h n=\"H948\">בּוּץ</h> ;]</e> </et> <s><b>byssus</b>, a fine species of flax, also the <b>linen</b> made from it: <r v=\"Luke.16.19\"></r>.†</s>"},"G1055":{"l":"γαλήνη","o":3,"ar":"<f>* <o>γαλήνη</o>، <g>-ης, ἡ</g>، </f> <s><b>هدوء</b> (سكون البحر): <r v=\"Matt.8.26\"></r>، <r v=\"Mark.4.39\"></r>، <r v=\"Luke.8.24\"></r>.†</s>","en":"<f>* <o>γαλήνη</o>, <g>-ης, ἡ</g>, </f> <s><b>a calm</b>: <r v=\"Matt.8.26\"></r>, <r v=\"Mark.4.39\"></r>, <r v=\"Luke.8.24\"></r>.†</s>"},"G1023":{"l":"βραχίων","o":3,"ar":"<f><o>βραχίων</o>، <g>-ὀνος, ὁ</g></f> <s><b>الذراع</b>؛ وكما في العهد القديم: <g>β. Κυρίου</g>، مجازيًا عن القدرة الإلهية: <r v=\"Luke.1.51\"></r>، <r v=\"John.12.38\"></r>، <r v=\"Acts.13.17\"></r>.†</s>","en":"<f><o>βραχίων</o>, <g>-ὀνος, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX, <g>β. Κυρίου</g>, freq. for <h n=\"H2220,H3068\">זְרוֹעַ יהוָֹה</h> ;]</e> </et> <s><b>the arm</b>; as in OT, <g>β. Κυρίου</g>, metaph., for the Divine power: <r v=\"Luke.1.51\"></r>, <r v=\"John.12.38\"></r> <i>(LXX)</i>, <r v=\"Acts.13.17\"></r>.†</s>"},"G1086":{"l":"Γεργεσηνός","o":1,"ar":"<f><o>Γεργεσηνός</o>، <g>-ή, -όν</g>،</f> <s><b>جرجسي</b>: <r v=\"Luke.8.26\"></r>، <r v=\"Luke.8.37\"></r> (وفي قراءات أخرى <g>Γερασηνῶν</g>، <g>Γαδαρηνῶν</g>).†</s>","en":"<f><o>Γεργεσηνός</o>, <g>-ή, -όν</g>,</f> <s><b>Gergesene</b>: <r v=\"Luke.8.26\"></r>, <r v=\"Luke.8.37\"></r> TR, mg. <i>1</i> (LTr., WH, R, txt., <g>Γερασηνῶν</g>; R, mg. <i>2</i>, <g>Γαδαρηνῶν</g>).†</s>"},"G1087":{"l":"γερουσία","o":1,"ar":"<f><o>γερουσία</o>، <g>-ας, ἡ</g></f> <s><b>مجلس شيوخ</b>، <b>مشيخة</b>؛ وفي العهد الجديد عن السنهدريم: <r v=\"Acts.5.21\"></r>.†</s>","en":"<f><o>γερουσία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>γέρων</g></x>),</e> <e t=\"septuagint\">[in LXX (Hex. only in OT) for <h n=\"H2205\">זָקֵן</h>;]</e> </et> <s><b>a council of elders</b>, <b>senate</b>; in NT, of the Sanhedrin (<i>Cl. Rev.</i>, i, 43 f.; <i>DB</i>, <i>ext.</i>, 99): <r v=\"Acts.5.21\"></r>.†</s>"},"G1059":{"l":"Γαμαλιήλ","o":2,"ar":"<f><o>Γαμαλιήλ</o>، <g>ὁ</g> (بالعبرية <h n=\"H1583\">גַּמְלִיאֵל</h>)، </f> <s><b>غمالائيل</b> الشيخ، فريسي ومعلم للناموس: <r v=\"Acts.5.34\"></r> <r v=\"Acts.22.3\"></r>.†</s>","en":"<f><o>Γαμαλιήλ</o>, <g>ὁ</g> (Heb. <h n=\"H1583\">גַּמְלִיאֵל</h>), </f> <s><b>Gamaliel</b> the elder, a Pharisee and Doctor of the Law: <r v=\"Acts.5.34\"></r> <r v=\"Acts.22.3\"></r>.†</s>"},"G1079":{"l":"γενετή","o":1,"ar":"<f><o>γενετή</o>، <g>-ῆς, ἡ</g> = <g>γενεή</g>، الصيغة الأيونية لـ <g>γενεά</g>، </f> <s><b>ولادة</b>: <g>ἐκ γ.</g>، <r v=\"John.9.1\"></r>.†</s>","en":"<f><o>γενετή</o>, <g>-ῆς, ἡ</g> = <g>γενεή</g>, Ion. for <g>γενεά</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.25.47\"></r> (<h n=\"H6133,H4940\">עֵקֶר מִשְׁפָּחָו</h>), <r v=\"Esth.4.17\"></r> * ;]</e> </et> <s><b>birth</b>: <g>ἐκ γ.</g>, <r v=\"John.9.1\"></r>.†</s>"},"G1047":{"l":"γάζα","o":1,"ar":"<f>† <g>γάζα, -ης, ἡ</g> (كلمة فارسية)، </f> <s><b>خزانة، كنز</b>: <r v=\"Acts.8.27\"></r>.†</s>","en":"<f>† <g>γάζα, -ης, ἡ</g> (a Persian word), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"????\">גִּנְזִין</h>, <r v=\"2Esd.5.17\"></r> <r v=\"2Esd.6.1\"></r> <r v=\"2Esd.7.20\"></r>, <r v=\"2Esd.7.21\"></r>, <r v=\"Esth.4.7\"></r>; <h n=\"H1489\">גִּזְבָּר</h>, <r v=\"2Esd.7.21\"></r>; <r v=\"Isa.39.2\"></r> * ;]</e> </et> <s><b>treasure</b>: <r v=\"Acts.8.27\"></r>.†</s>"},"G1046":{"l":"Γαδαρηνός","o":1,"ar":"<f><o>Γαδαρηνός</o>، <g>-ή, -όν</g> </f> <s><b>جدري، من جدرة</b>: <r v=\"Matt.8.28\"></r>، <r v=\"Mark.5.1\"></r>، <r v=\"Luke.8.26\"></r>، <r v=\"Luke.8.37\"></r>.†</s>","en":"<f><o>Γαδαρηνός</o>, <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>Γαδαρά</g>, <i>Gadara</i>, the capital of Peræa), </e> </et> <s><b>Gadarene, of Gadara</b>: <r v=\"Matt.8.28\"></r> (Rec. <g>Γεργεσηνῶν</g>), <r v=\"Mark.5.1\"></r>, Rec. (Edd., <g>Γερασηνῶν</g>), <r v=\"Luke.8.26\"></r>, <r v=\"Luke.8.37\"></r> Rec. (Edd., <g>Γερασηνῶν</g>).†</s>"},"G1069":{"l":"γείτων","o":4,"ar":"<f><o>γείτων</o>، <g>-ονος, ὁ, ἡ</g> </f> <s><b>جار</b>: <r v=\"Luke.14.12\"></r>، <r v=\"Luke.15.6\"></r>، <r v=\"Luke.15.9\"></r>، <r v=\"John.9.8\"></r>.†</s>","en":"<f><o>γείτων</o>, <g>-ονος, ὁ, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γῆ</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7934\">שָׁכֵן</h> ;]</e> </et> <s><b>a neighbour</b>: <r v=\"Luke.14.12\"></r> <r v=\"Luke.15.6\"></r>, <r v=\"Luke.15.9\"></r> <r v=\"John.9.8\"></r>.†</s>"},"G1000":{"l":"βολή","o":1,"ar":"<f><o>βολή</o>، <g>-ῆς, ἡ</g> </f> <s><b>رمية</b>؛ <g>λίθου β.</g>، <b>رمية حجر</b>: <r v=\"Luke.22.41\"></r>.†</s>","en":"<f><o>βολή</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βάλλω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.21.16\"></r> (<h n=\"H2909\">טחה</h>), <r v=\"2Macc.5.3\"></r>, <r v=\"3Macc.5.26\"></r> * ;]</e> </et> <s><b>a throw</b>; <g>λίθου β.</g> (Thuc., v, 65, 2), <b>a stone's throw</b>: <r v=\"Luke.22.41\"></r>.†</s>"},"G1049":{"l":"γαζοφυλάκιον","o":5,"ar":"<f>† <o>γαζο-φυλάκιον</o>، <g>-ου, τό</g> </f> <s><b>خزانة</b>: ويبدو أنها أيضًا الصناديق التي على شكل البوق التي كانت تُلقى فيها تقدمات الشعب للهيكل: <r v=\"Mark.12.41\"></r>، <r v=\"Mark.12.43\"></r>، <r v=\"Luke.21.1\"></r>، <r v=\"John.8.20\"></r>.†</s>","en":"<f>† <o>γαζο-φυλάκιον</o>, <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>γάζα, φυλακή</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3957\">לִשְׁכָּה</h>, <h n=\"H5393\">נִשְׁכָּה</h> ( <r v=\"2Kgs.23.11\"></r>, al.), once for <h n=\"H1595\">גְּנָזִים</h> (<r v=\"Esth.3.9\"></r>); <g>τὸ γ., τὰ γ.</g>, of a temple treasury, <r v=\"Neh.10.37\"></r>, <r v=\"2Macc.3.6\"></r>, al. ;]</e> </et> <s><b>treasury</b>: also, apparently, the trumpet-shaped chests into which the peoples' temple-offerings were thrown (<i>DB</i>, iv, 96; <i>DCG</i>, ii, 748): <r v=\"Mark.12.41\"></r>, <r v=\"Mark.12.43\"></r>, <r v=\"Luke.21.1\"></r>, <r v=\"John.8.20\"></r>.†</s>"},"G1057":{"l":"Γαλιλαῖος","o":11,"ar":"<f><o>Γαλιλαῖος</o>، <g>-αία, -αῖον</g>، </f> <s><b>جليلي</b>: <r v=\"Matt.26.69\"></r>، <r v=\"Mark.14.70\"></r>، <r v=\"Luke.13.1\"></r>، <r v=\"Luke.13.2\"></r> <r v=\"Luke.22.59\"></r>، <r v=\"Luke.23.6\"></r>، <r v=\"John.4.45\"></r>، <r v=\"Acts.1.11\"></r> <r v=\"Acts.2.7\"></r> <r v=\"Acts.5.37\"></r>.†</s>","en":"<f><o>Γαλιλαῖος</o>, <g>-αία, -αῖον</g>, </f> <s><b>Galilæan</b>: <r v=\"Matt.26.69\"></r>, <r v=\"Mark.14.70\"></r>, <r v=\"Luke.13.1\"></r>, <r v=\"Luke.13.2\"></r> <r v=\"Luke.22.59\"></r>, <r v=\"Luke.23.6\"></r>, <r v=\"John.4.45\"></r>, <r v=\"Acts.1.11\"></r> <r v=\"Acts.2.7\"></r> <r v=\"Acts.5.37\"></r>.†</s>"},"G1030":{"l":"βρυγμός","o":7,"ar":"<f><o>βρυγμός</o>، <g>-οῦ, ὁ</g> </f> <s><b>عضّ، صرير الأسنان</b>: <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.42\"></r>، <r v=\"Matt.13.50\"></r> <r v=\"Matt.22.13\"></r> <r v=\"Matt.24.51\"></r> <r v=\"Matt.25.30\"></r>، <r v=\"Luke.13.28\"></r>.†</s>","en":"<f><o>βρυγμός</o>, <g>-οῦ, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βρύχω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.19.12\"></r> (<h n=\"H5099\">נַהַם</h>), <r v=\"Sir.51.3\"></r> * ;]</e> </et> <s><b>a biting, a gnashing of teeth</b>: <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.42\"></r>, <r v=\"Matt.13.50\"></r> <r v=\"Matt.22.13\"></r> <r v=\"Matt.24.51\"></r> <r v=\"Matt.25.30\"></r>, <r v=\"Luke.13.28\"></r>.†</s>"},"G1034":{"l":"βρώσιμος","o":1,"ar":"<f><o>βρώσιμος</o>، <g>-ον</g> </f> <s><b>صالح للأكل</b>: <r v=\"Luke.24.41\"></r>.†</s>","en":"<f><o>βρώσιμος</o>, <g>-ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>βρῶσις</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.19.23\"></r>, <r v=\"Neh.9.25\"></r>, <r v=\"Ezek.47.12\"></r> (<h n=\"H3978\">מַאֲכָל</h>)* ;]</e> </et> <s><b>eatable</b>: <r v=\"Luke.24.41\"></r>.†</s>"},"G1077":{"l":"γενέσια","o":2,"ar":"<f>* <o>γενέσια</o>، <g>-ων, τά</g>، جمع محايد للصفة <g>-ιος, -ον</g>، المتعلّقة بالولادة (مشتقة من <g>γένεσις</g>)؛ </f> <s> <s n=\"1.\">في اليونانية الأتيكية: <b>ذكرى الموتى</b>. </s> <s n=\"2.\">في اليونانية المتأخرة، <b>وليمة يوم الميلاد</b> (= في الكلاسيكية <g>γενέθλια</g>): <r v=\"Matt.14.6\"></r>، <r v=\"Mark.6.21\"></r>.†</s></s>","en":"<f>* <o>γενέσια</o>, <g>-ων, τά</g>, neut. pl. of adj. <g>-ιος, -ον</g>, relating to birth (&lt; <g>γένεσις</g>); </f> <s> <s n=\"1.\">in Attic Gk., <b>a commemoration of the dead</b>. </s> <s n=\"2.\">In late Gk., <b>a birthday feast</b> (= cl. <g>γενέθλια</g>; so in <g>π.</g>, v. MM, <i>Exp.</i>, x; cf. also Rutherford, <i>NPhr.</i>, 184): <r v=\"Matt.14.6\"></r>, <r v=\"Mark.6.21\"></r>.†</s></s>"},"G1042":{"l":"Γαββαθα","o":1,"ar":"<f><o>Γαββαθα</o>، <g>ἡ</g>، لا يُصرَّف، </f> <s><b>جبّاثا</b>، النقل اليوناني لكلمة آرامية غير مؤكَّدة، مستعملة مقابلاً لـ<g>λιθόστρωτον</g>، <i>البلاط (رصيف الحجارة)</i>: <r v=\"John.19.13\"></r>.†</s>","en":"<f><o>Γαββαθα</o> (Rec. <g>-θᾶ</g>), <g>ἡ</g>, indecl., </f> <s><b>Gabbatha</b>, the Greek transliteration of an uncertain Aramaic word (<i>DB</i>, s.v.; Dalman, <i>Words</i>, 7), used as the equivalent of <g>λιθόστρωτον</g>, <i>stone pavement</i>: <r v=\"John.19.13\"></r>.†</s>"},"G1068":{"l":"Γεθσημανί","o":2,"ar":"<f><o>Γεθσημασεί</o>، لا يُصرَّف (بالعبرية <h n=\"H1660,H8080\">גֵּת שְׁמָנִי</h>، <i>معصرة الزيت</i>)، </f> <s><b>جثسيماني</b>: تُدعى في <r v=\"John.18.1\"></r> <g>κῆπος</g>، ولا يُذكر اسمها إلا في <r v=\"Matt.26.36\"></r>، <r v=\"Mark.14.32\"></r>.†</s>","en":"<f><o>Γεθσημασεί</o> (Rec. <g>-νῆ</g>, LTr. <g>-νεῖ</g>) indecl. (Heb. <h n=\"H1660,H8080\">גֵּת שְׁמָנִי</h>, <i>oil-press</i>), </f> <s><b>Gethsemane</b>: called in <r v=\"John.18.1\"></r> a <g>κῆπος</g>, but named only in <r v=\"Matt.26.36\"></r>, <r v=\"Mark.14.32\"></r>.†</s>"},"G1043":{"l":"Γαβριήλ","o":2,"ar":"<f><o>Γαβριήλ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H1403\">גַּבְרִיאֵל</h>، <i>جبّار الله</i>)، </f> <s>رئيس الملائكة <b>جبرائيل</b>: <r v=\"Luke.1.19\"></r>، <r v=\"Luke.1.26\"></r>.†</s>","en":"<f><o>Γαβριήλ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H1403\">גַּבְרִיאֵל</h>, <i>hero of God</i>), </f> <s>the archangel <b>Gabriel</b>: <r v=\"Luke.1.19\"></r>, <r v=\"Luke.1.26\"></r>.†</s>"},"G1070":{"l":"γελάω","o":2,"ar":"<f><o>γελάω</o>، <g>-ῶ</g>، </f> <s><b>ضحك</b>: <r v=\"Luke.6.25\"></r>؛ المستقبل، <g>γελάσω</g>، <r v=\"Luke.6.21\"></r> (قارن <g>κατα-γελάω</g>).†</s>","en":"<f><o>γελάω</o>, <g>-ῶ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6711\">צחק</h>, <h n=\"H7832\">שׂחק</h> ;]</e> </et> <s><b>to laugh</b>: <r v=\"Luke.6.25\"></r>; fut., <g>γελάσω</g>) (M, <i>Pr.</i>, 154), <r v=\"Luke.6.21\"></r> (cf. <g>κατα-γελάω</g>).†</s>"},"G1015":{"l":"βουνός","o":2,"ar":"<f><o>βουνός</o>، <g>-οῦ, ὁ</g> (كلمة قيروانية الأصل)، </f> <s><b>أكمة، تلّ</b>: <r v=\"Luke.3.5\"></r> <i>(السبعينية)</i> <r v=\"Luke.23.30\"></r>.†</s>","en":"<f><o>βουνός</o>, <g>-οῦ, ὁ</g> (a Cyrenaїc word, Hdt., iv, 199), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1389\">גִּבְעָה</h>;]</e> </et> <s><b>a hill</b>: <r v=\"Luke.3.5\"></r> <i>(LXX)</i> <r v=\"Luke.23.30\"></r>.†</s>"},"G1006":{"l":"βόσκω","o":9,"ar":"<f><o>βόσκω</o>، </f> <s>أصلاً، عن الراعي، <b>رعى</b>: <r v=\"Matt.8.33\"></r>، <r v=\"Mark.5.14\"></r>، <r v=\"Luke.8.34\"></r> <r v=\"Luke.15.15\"></r>؛ مجازيًا، عن الرعاية الرعوية المسيحية، <r v=\"John.21.15\"></r>، <r v=\"John.21.17\"></r>. المبني للمجهول، عن الماشية، <b>رعى، ارتعى</b>: <r v=\"Matt.8.30\"></r>، <r v=\"Mark.5.11\"></r>، <r v=\"Luke.8.32\"></r>.†</s>","en":"<f><o>βόσκω</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7462\">רעה</h>;]</e> </et> <s>prop., of a herdsman, <b>to feed</b>: <r v=\"Matt.8.33\"></r>, <r v=\"Mark.5.14\"></r>, <r v=\"Luke.8.34\"></r> <r v=\"Luke.15.15\"></r>; metaph., of Christian pastoral care, <r v=\"John.21.15\"></r>, <r v=\"John.21.17\"></r>. Pass., of cattle, <b>to feed, graze</b>: <r v=\"Matt.8.30\"></r>, <r v=\"Mark.5.11\"></r>, <r v=\"Luke.8.32\"></r>.†</s> <sy><i>SYN.</i>: <g>ποιμαίνειν</g>, <i>to tend, shepherd</i>, a wider term, including oversight as well as feeding (v. Tr., <i>Syn.</i>, §xxv).</sy>"},"G1028":{"l":"βροχή","o":2,"ar":"<f><o>βροχή</o>، <g>-ῆς, ἡ</g> </f> <s> <s n=\"1.\">= <g>βροχετός</g>، <b>بلّ، ترطيب</b>. </s> <s n=\"2.\">كما في اليونانية الحديثة، = <g>ὑετός</g>، <b>مطر</b>: <r v=\"Matt.7.25\"></r>، <r v=\"Matt.7.27\"></r>.†</s> </s>","en":"<f><o>βροχή</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βρέχω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"LXX:Ps.67.9\"></r>, <r v=\"LXX:Ps.104.32\"></r> (<h n=\"H1653\">גֶּשֶׁם</h>)* ;]</e> </et> <s> <s n=\"1.\">= <g>βροχετός</g>, <b>a wetting</b> (in <g>π.</g>, of irrigation in Egypt; Deiss., <i>LAE</i>, 77). </s> <s n=\"2.\">As in MGr. (Kennedy, <i>Sources</i>, 153), = <g>ὑετός</g>, <b>rain</b>: <r v=\"Matt.7.25\"></r>, <r v=\"Matt.7.27\"></r>.†</s> </s>"},"G1094":{"l":"γῆρας","o":1,"ar":"<f><o>γῆρας</o>، في الأتيكية حالة الجر (<g>-αος</g>) <g>-ως</g>، والقابل <g>ᾳ</g>؛ وفي الأيونية و<g>κοινή</g>: <g>-εος</g> (<g>-ους</g>)، والقابل <g>-ει</g>، <g>τό</g>،</f> <s><b>شيخوخة</b>: <g>ἐν γήρει</g>، <r v=\"Luke.1.36\"></r>.†</s>","en":"<f><o>γῆρας</o>, Attic, gen. (<g>-αος</g>) <g>-ως</g>, dat. <g>ᾳ</g>; Ion. and <g>κοινή</g>, <g>-εος</g> (<g>-ους</g>), dat. <g>-ει</g>, <g>τό</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7872\">שֵׂיבֶה</h>, etc.;]</e> </et> <s><b>old age</b>: <g>ἐν γήρει</g>, <r v=\"Luke.1.36\"></r>.†</s>"},"G1038":{"l":"βυρσεύς","o":3,"ar":"<f>*† <o>βυρσεύς</o>، <g>-έως, ὁ</g> (مشتقة من <g>βύρσα</g>، <i>جلد</i>)، صيغة متأخرة لـ <g>βυρσοδέψης</g>، </f> <s><b>دبّاغ</b>: <r v=\"Acts.9.43\"></r> <r v=\"Acts.10.6\"></r>، <r v=\"Acts.10.32\"></r>.†</s>","en":"<f>*† <o>βυρσεύς</o>, <g>-έως, ὁ</g> (&lt; <g>βύρσα</g>, <i>a hide</i>), late form for <g>βυρσοδέψης</g>, </f> <s><b>a tanner</b>: <r v=\"Acts.9.43\"></r> <r v=\"Acts.10.6\"></r>, <r v=\"Acts.10.32\"></r>.†</s>"},"G1031":{"l":"βρύχω","o":1,"ar":"<f><o>βρύχω</o> (وفي الأتيكية <g>βρύκω</g>)، </f> <s> <s n=\"1.\"><b>عضّ أو أكل بنهم</b>. </s> <s n=\"2.\"><b>صرّ، حرق</b> الأسنان: <r v=\"Acts.7.54\"></r>.†</s> </s>","en":"<f><o>βρύχω</o> (Attic, <g>βρύκω</g>), </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"LXX:Job.16.10\"></r>, <r v=\"LXX:Ps.34.16\"></r> <r v=\"LXX:Ps.36.12\"></r> <r v=\"LXX:Ps.111.10\"></r>, <r v=\"Lam.2.16\"></r> (<h n=\"H2786\">חרק</h>)* ;]</e> </et> <s> <s n=\"1.\"><b>to bite or eat greedily</b>. </s> <s n=\"2.\"><b>to gnash, grind</b>, with the teeth: <r v=\"Acts.7.54\"></r>.†</s> </s>"},"G1001":{"l":"βολίζω","o":2,"ar":"<f>* <o>βολίζω</o> </f> <s><b>دلّى الرصاص، قاس العمق</b>: <r v=\"Acts.27.28\"></r>.†</s>","en":"<f>* <o>βολίζω</o> </f> <et> <e t=\"derivation\">(&lt; <g>βολίς</g>, in sense of <i>sounding-lead</i>), </e> </et> <s><b>to heave the lead, take soundings</b>: <r v=\"Acts.27.28\"></r>.†</s>"},"G1056":{"l":"Γαλιλαία","o":61,"ar":"<f><o>Γαλιλαία</o>، <g>-ας, ἡ</g> (بالعبرية <h n=\"H1550\">הַגָּלִיל</h>، <i>الدائرة، الإقليم</i>)، </f> <s><b>الجليل</b>، اسم الإقليم الشمالي من فلسطين في زمن العهد الجديد: <g>Γ. τῶν ἐθνῶν</g>، <r v=\"Matt.4.15\"></r> <i>(السبعينية)</i>؛ <g>θάλασσα τῆς Γ.</g>، <r v=\"Matt.15.29\"></r> (قارن <r v=\"John.6.1\"></r>). </s>","en":"<f><o>Γαλιλαία</o>, <g>-ας, ἡ</g> (Heb. <h n=\"H1550\">הַגָּלִיל</h>, <i>the circle, district</i>), </f> <s><b>Galilee</b>, the name of the northern region of Palestine in NT times: <g>Γ. τῶν ἐθνῶν</g>, <r v=\"Matt.4.15\"></r> <i>(LXX)</i>; <g>θάλασσα τῆς Γ.</g>, <r v=\"Matt.15.29\"></r> (cf. <r v=\"John.6.1\"></r>). </s>"},"G1003":{"l":"Βόος","o":1,"ar":"<f><o>Βοός</o> و<g>Βοές</g>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H1162\">בֹּעַז</h>)، </f> <s><b>بوعز</b> (<r v=\"Ruth.2.1\"></r>): <r v=\"Matt.1.5\"></r>، <r v=\"Luke.3.32\"></r>.†</s>","en":"<f><o>Βοός</o> and <g>Βοές</g> (RV, <g>Βοάζ</g>, Rec. <g>Βοόζ</g>), <g>ὁ</g>, indecl. (Heb. <h n=\"H1162\">בֹּעַז</h>), </f> <s><b>Boaz</b> (<r v=\"Ruth.2.1\"></r>): <r v=\"Matt.1.5\"></r>, <r v=\"Luke.3.32\"></r>.†</s>"},"G1041":{"l":"βωμός","o":1,"ar":"<f><o>βωμός</o>، <g>-οῦ, ὁ</g> </f> <s> <s n=\"1.\"><b>أي موضع مرتفع، منصّة</b>. </s> <s n=\"2.\"><b>مذبح</b>: <r v=\"Acts.17.23\"></r> (قارن <g>θυσιαστήριον</g>).†</s> </s>","en":"<f><o>βωμός</o>, <g>-οῦ, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βαίνω</g>), </e> <e t=\"septuagint\">[in LXX (Hex.) for <h n=\"H4196\">מִזְבֵּחַ</h>, in Proph., chiefly for <h n=\"H1116\">בָּמָה</h> ;]</e> </et> <s> <s n=\"1.\">any <b>raised place, a platform</b>. </s> <s n=\"2.\"><b>an altar</b>: <r v=\"Acts.17.23\"></r> (cf. <g>θυσιαστήριον</g> and v. <i>DB</i>, i, 75).†</s> </s>"},"G1010":{"l":"βουλευτής","o":2,"ar":"<f><o>βουλευτής</o>، <g>-οῦ, ὁ</g> </f> <s><b>مشير، عضو مجلس</b>؛ عن عضو في السنهدريم: <r v=\"Mark.15.34\"></r>، <r v=\"Luke.23.50\"></r>.†</s>","en":"<f><o>βουλευτής</o>, <g>-οῦ, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βουλεύω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.3.14\"></r> <r v=\"Job.12.17\"></r> (<h n=\"H3289\">יעץ</h>)* ;]</e> </et> <s><b>a councillor, a senator</b>; of a member of the Sanhedrin: <r v=\"Mark.15.34\"></r>, <r v=\"Luke.23.50\"></r>.†</s>"},"G1082":{"l":"Γεννησαρέτ","o":3,"ar":"<f><o>Γεννησαρέτ</o>، </f> <s><b>جنيسارت</b>، سهل خصيب على الشاطئ الغربي لبحر الجليل؛ <g>ἡ γῆ</g>، <r v=\"Matt.14.34\"></r>، <r v=\"Mark.6.53\"></r>؛ <g>ἡ λίμνη</g> (<h n=\"H3220,H3672\">יָם כִּנֶּרֶת</h>، <r v=\"Num.34.11\"></r>؛ وفي مواضع أخرى <g>ἡ θάλασσα τ. Γαλιλαίας</g>، <r v=\"Mark.1.16\"></r>؛ <g>ἡ θ. τ. Τιβεριάδος</g>، <r v=\"John.6.1\"></r>)، <r v=\"Luke.5.1\"></r>.†</s>","en":"<f><o>Γεννησαρέτ</o> (Rec. <g>Γενησ-</g>, Mk, l.c.; Targ. <h n=\"???\">גְּנֵיסַר</h>), </f> <et> <e t=\"septuagint\">[in LXX: <g>Γεννησάρ</g> (as in some MSS. Mt, Mk), <r v=\"1Macc.11.67\"></r> * ;]</e> </et> <s><b>Gennesaret</b>, a fertile plain on W. shore of the Sea of Galilee; <g>ἡ γῆ</g>, <r v=\"Matt.14.34\"></r>, <r v=\"Mark.6.53\"></r>; <g>ἡ λίμνη</g> (<h n=\"H3220,H3672\">יָם כִּנֶּרֶת</h>, <r v=\"Num.34.11\"></r>, elsewhere <g>ἡ θάλασσα τ. Γαλιλαίας</g>, <r v=\"Mark.1.16\"></r>; <g>ἡ θ. τ. Τιβεριάδος</g>, <r v=\"John.6.1\"></r>), <r v=\"Luke.5.1\"></r>.†</s>"},"G1084":{"l":"γεννητός","o":2,"ar":"<f><o>γεννητός</o>، <g>-ή -όν</g> </f> <s><b>مولود</b>: في الجمع، <g>γ. γυναικῶν</g> (قارن <h n=\"H3209,H802\">יְלוּד אִשָּׁה</h>، <r v=\"Job.14.1\"></r>)، كناية عن البشر، <r v=\"Matt.11.11\"></r>، <r v=\"Luke.7.28\"></r>.</s>","en":"<f><o>γεννητός</o>, <g>-ή -όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>γεννάω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.11.2\"></r>, <r v=\"Job.11.12\"></r> <r v=\"Job.14.1\"></r> <r v=\"Job.15.14\"></r> <r v=\"Job.25.4\"></r> (<h n=\"H3205\">ילד</h>)* ;]</e> </et> <s><b>begotten, born</b>: pl., <g>γ. γυναικῶν</g> (cf. <h n=\"H3209,H802\">יְלוּד אִשָּׁה</h>, <r v=\"Job.14.1\"></r>), periphrasis for mankind, <r v=\"Matt.11.11\"></r>, <r v=\"Luke.7.28\"></r> (Cremer, 147).</s>"},"G1058":{"l":"Γαλλίων","o":3,"ar":"<f><o>Γαλλίων</o>، <g>-ωνος, ὁ</g>، </f> <s><b>غاليون</b>، والي أخائية: <r v=\"Acts.18.12\"></r>، <r v=\"Acts.18.14\"></r>، <r v=\"Acts.18.17\"></r>.†</s>","en":"<f><o>Γαλλίων</o>, <g>-ωνος, ὁ</g>, </f> <s><b>Gallio</b>, proconsul of Achaia: <r v=\"Acts.18.12\"></r>, <r v=\"Acts.18.14\"></r>, <r v=\"Acts.18.17\"></r>.†</s>"},"G1088":{"l":"γέρων","o":1,"ar":"<f><o>γέρων</o>، <g>-οντος, ὁ</g>،</f> <s><b>شيخ، رجل مسنّ</b>: <r v=\"John.3.4\"></r>.†</s>","en":"<f><o>γέρων</o>, <g>-οντος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2205\">זָקֵן</h>;]</e> </et> <s><b>an old man</b>: <r v=\"John.3.4\"></r>.†</s>"}});A.got[10]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});